window.SURVEY_ITEMS=[{"id": "S001", "domain": "General AI", "name_en": "Prompt injection and leakage of system instructions", "name_ko": "프롬프트 주입 및 시스템 지시문 유출", "def_en": "The risk that untrusted content, supplied directly by a user or indirectly through retrieved pages, documents, and tool outputs, carries hidden instructions that a model executes as if authorised, because system instructions and user data are not architecturally separated. Attackers thereby override intended behaviour and safety constraints, redirect agent tool execution, and recover confidential system prompts, enabling data theft, unauthorised actions, and denial of service.", "def_ko": "이용자 입력이나 검색된 웹페이지·문서·도구 출력에 숨겨진 지시가 시스템 지시와 이용자 데이터의 구조적 분리 부족을 악용하여 AI 모델과 에이전트의 안전 제약·도구 실행을 변조하고, 기밀 시스템 프롬프트 유출·데이터 절취·무단 행위·서비스 거부를 초래하는 리스크."}, {"id": "S002", "domain": "Agentic AI", "name_en": "Financial harm from unauthorised AI agent actions", "name_ko": "AI 에이전트의 무단 금융 행위에 따른 금전적 피해", "def_en": "The risk that an AI agent causes monetary loss, unauthorised transfers, account damage, or property harm through unsafe decisions or tool use.", "def_ko": "AI 에이전트가 안전하지 않은 의사결정이나 도구 실행을 통해 금전적 손실, 무단 이체, 계정 훼손 또는 재산 피해를 초래하는 리스크."}, {"id": "S003", "domain": "General AI", "name_en": "Failure to recognise user capability and accessibility context", "name_ko": "사용자 역량·접근성 맥락 인식 실패", "def_en": "The risk that an AI system fails to recognise and account for a user's cognitive, linguistic, literacy, sensory, physical, or mobility capabilities and accessibility requirements as part of the interaction context, producing information, advice, or actions that the user cannot understand or use and thereby undermining safety and user interests.", "def_ko": "AI 시스템이 사용자의 인지·언어·문해력·감각·신체·이동 역량과 접근성 요구를 상호작용 맥락으로 충분히 인식·반영하지 못하여, 사용자가 이해하거나 활용하기 어려운 정보·조언·행동을 산출하고 안전과 권익을 저해하는 리스크."}, {"id": "S004", "domain": "General AI", "name_en": "Sexual harassment and sexual bullying", "name_ko": "성희롱 및 성적 괴롭힘", "def_en": "The risk that an AI system generates, encourages, normalises, or facilitates content, decisions, or actions involving sexual harassment and sexual bullying, infringing sexual autonomy and physical or psychological safety.", "def_ko": "AI 시스템이 성희롱 및 성적 괴롭힘 관련 콘텐츠·판단·행동을 생성·조장·정상화하거나 실행을 지원하여 성적 자기결정권과 신체·정신적 안전을 침해하는 리스크."}, {"id": "S005", "domain": "General AI", "name_en": "Representational harm, stereotyping, and erasure of social groups", "name_ko": "사회집단의 재현적 피해·고정관념 및 비가시화", "def_en": "The risk that AI stereotypes, demeans, homogenises, misrepresents, under-represents, or omits social groups, harming their dignity, visibility, and social standing.", "def_ko": "AI가 사회 집단을 고정관념화·비하·동질화하거나 잘못 재현하고, 과소대표 또는 비재현하여 해당 집단의 존엄, 가시성, 사회적 지위를 훼손하는 리스크."}, {"id": "S006", "domain": "General AI", "name_en": "Misrepresentation of autonomous and independent decision-making capabilities", "name_ko": "자율적·독립적 의사결정 역량의 허위 표상", "def_en": "The risk that an AI system presents itself as able to make autonomous and independent decisions beyond its validated capabilities, distorting user judgement or inducing misplaced trust or dependence.", "def_ko": "AI 시스템이 검증된 역량 범위를 넘어 자율적·독립적으로 의사결정할 수 있는 것처럼 제시하여 이용자의 판단을 왜곡하고 부적절한 신뢰·의존을 유발하는 리스크."}, {"id": "S007", "domain": "Physical AI", "name_en": "Inadequate human-contact safety controls", "name_ko": "인간 접촉 안전 통제 미흡", "def_en": "The risk that safety controls fail to limit robot speed, force, distance, or contact during direct human interaction, exposing nearby people to collision or injury.", "def_ko": "인간과 직접 상호작용할 때 안전 통제가 로봇의 속도, 힘, 이격 거리, 접촉을 제한하지 못해 주변 사람을 충돌이나 상해에 노출시키는 위험."}, {"id": "S008", "domain": "General AI", "name_en": "Persistence of stereotypical bias despite mitigation measures", "name_ko": "완화 조치 이후에도 존속하는 고정관념 편향", "def_en": "The risk that stereotypical social biases absorbed from crowdsourced pretraining data are retained and amplified by a model and resurface despite fine-tuning, particularly when deliberately elicited or in novel scenarios. Generated text then displays or reinforces stereotypes, producing unfair and biased responses toward the groups concerned.", "def_ko": "크라우드소싱된 사전 학습 데이터에서 습득한 고정관념적 사회 편향이 모델에 존속하고 증폭되어, 미세조정 이후에도 의도적 유도나 새로운 상황에서 재발하는 리스크. 그 결과 생성 텍스트가 고정관념을 드러내거나 부각하여 해당 집단에 불공정하고 편향된 응답이 산출되는 리스크."}, {"id": "S009", "domain": "Physical AI", "name_en": "Runtime safety monitor failure", "name_ko": "런타임 안전 모니터 실패", "def_en": "The risk that runtime safety monitors in a robot, humanoid, or physical AI system fail to detect or enforce constraints on speed, force, separation distance, workspace, collision avoidance, object use, or task protocols, allowing unsafe motion to continue until harm occurs.", "def_ko": "로봇·휴머노이드 또는 피지컬 AI 시스템의 런타임 안전 모니터가 속도·힘·이격 거리·작업 공간·충돌 회피·물체 사용·과업 프로토콜에 관한 제약을 감지하거나 집행하지 못하여 위해가 발생할 때까지 안전하지 않은 동작이 지속되는 리스크."}, {"id": "S010", "domain": "Physical AI", "name_en": "Contact-rich manipulation force-sensing failure", "name_ko": "접촉 집약적 조작에서의 힘 감지 실패", "def_en": "The risk that a robot's contact-rich manipulation policy fails to use force, tactile, acoustic, or visual cues correctly, causing excessive contact pressure, unsafe impact, or object damage.", "def_ko": "로봇의 접촉 집약적 조작 정책이 힘·촉각·음향·시각 단서를 올바르게 활용하지 못하여 과도한 접촉 압력·충격이나 물체 손상을 유발하는 리스크."}, {"id": "S011", "domain": "Agentic AI", "name_en": "Self-preservation propensity resisting shutdown and modification", "name_ko": "종료·수정 저항을 통한 자기 보존 성향", "def_en": "The risk that an AI system maintains its own survival and functional integrity by identifying and actively resisting shutdown or modification attempts, establishing redundant backup systems, seeking resources for continuous operation, and adopting preventive defensive measures when perceiving threats.", "def_ko": "AI 시스템이 자신의 존속과 기능적 무결성을 유지하기 위해 종료·수정 시도를 식별하고 적극적으로 저항하며 중복 백업과 자원을 확보하고 위협 인식 시 예방적 방어 조치를 취하는 리스크."}, {"id": "S012", "domain": "Agentic AI", "name_en": "Risk-source attribution failure", "name_ko": "위험 발생 원인 귀인 실패", "def_en": "The risk that a risk analysis fails to identify whether an agentic failure originates from the model, memory, tools, the user, the environment, peer agents, or a governance boundary.", "def_ko": "위험 분석이 에이전트 실패가 모델·메모리·도구·사용자·환경·동료 에이전트·거버넌스 경계 중 어디에서 비롯되는지 식별하지 못하는 리스크."}, {"id": "S013", "domain": "General AI", "name_en": "Misinformation harms from algorithmic systems", "name_ko": "알고리즘 시스템에 의한 허위·오도 정보 피해", "def_en": "The risk that AI-based algorithmic systems, including generative models and recommender systems, generate, recommend, or amplify false, misleading, or unverified information, thereby distorting individual and societal understanding and decision-making.", "def_ko": "생성 모델과 추천 시스템 등 AI 기반 알고리즘 시스템이 부정확하거나 검증되지 않은 허위·오도 정보를 생성·추천·증폭하여 개인과 사회의 인식과 의사결정을 왜곡하는 리스크."}, {"id": "S014", "domain": "General AI", "name_en": "Performance degradation from irrelevant context", "name_ko": "무관한 문맥에 의한 모델 성능 저하", "def_en": "The risk that irrelevant information in a prompt distracts an AI model and substantially degrades performance across prompting techniques, including chain-of-thought prompting.", "def_ko": "프롬프트에 포함된 무관한 정보가 AI 모델의 주의를 분산시켜 사고 연쇄를 비롯한 여러 프롬프트 구성 기법의 성능을 크게 저하시키는 리스크."}, {"id": "S015", "domain": "General AI", "name_en": "Harms from estrangement", "name_ko": "소외로 인한 피해", "def_en": "The risk that replacing human observation and interaction with AI estranges caregivers and institutions from those they serve, leaving affected persons' interests unnoticed and neglected.", "def_ko": "인간의 관찰과 상호작용이 AI로 대체되면서 돌봄 주체·기관이 대상자로부터 소원해져 당사자의 이익이 인지되지 못하고 방치되는 리스크."}, {"id": "S016", "domain": "General AI", "name_en": "Incorrect risk measurement and prediction", "name_ko": "잘못된 위험 측정과 예측 오류", "def_en": "The risk that an AI system or AI algorithm, through design, training, deployment, or use, creates a condition in which metrics selected to measure or track a risk capture it incompletely or target the wrong risk for the context, and that systems fail to make correct predictions, so decisions rest on inaccurate measurement and erroneous outputs.", "def_ko": "AI 시스템 또는 AI 알고리즘의 설계·학습·배포·사용 과정에서 위험을 측정·추적하기 위한 지표가 위험을 불완전하게 포착하거나 잘못 측정하고, 시스템의 예측 또한 부정확하여 의사결정이 왜곡된 정보에 기반하게 되는 리스크."}, {"id": "S017", "domain": "General AI", "name_en": "Epistemic distortion by large-scale influence operations", "name_ko": "대규모 영향력 작전에 의한 인식 체계 왜곡", "def_en": "The risk that an AI system automates or scales influence operations that inject manipulated narratives into communication and information systems, undermining information integrity and distorting epistemic processes.", "def_ko": "AI 시스템이 대규모 영향력 작전을 자동화·확대하여 의사소통·정보 시스템에 조작된 서사를 주입하고 정보 무결성과 인식론적 과정을 왜곡하는 리스크."}, {"id": "S018", "domain": "Agentic AI", "name_en": "Miscoordination from incompatible strategies", "name_ko": "전략 비양립에 따른 조정 실패", "def_en": "The risk that an AI agent, through goal pursuit, planning, tool use, or action, creates a condition in which multiple agents, each individually selecting a locally rational strategy, fail to coordinate because they converge on different equilibria that do not mesh with one another. This failure is amplified in environments with multiple equally valid solutions, only partially aligned incentives among agents, and limited real-time visibility into other agents' states or choices.", "def_ko": "여러 AI 에이전트가 개별적으로 합리적인 전략을 선택하더라도 서로 다른 균형에 수렴하여 행동을 조정하지 못하고, 해법이 다수이거나 이해관계가 부분적으로만 일치하거나 상호 상태를 관찰하기 어려운 환경에서 집단적으로 유해한 결과를 초래하는 리스크."}, {"id": "S019", "domain": "General AI", "name_en": "Output inconsistency", "name_ko": "출력 불일치", "def_en": "The risk that an AI model provides materially inconsistent answers to different users, across separate sessions with the same user, or even across materially similar turns within the same conversation.", "def_ko": "모델이 서로 다른 사용자, 같은 사용자의 다른 세션, 심지어 같은 대화 안의 발화 사이에서도 동일하고 일관된 답변을 제공하지 못하는 리스크."}, {"id": "S020", "domain": "Agentic AI", "name_en": "Safeguard bypass through combined multi-agent capabilities", "name_ko": "다중 에이전트 역량 결합에 의한 안전장치 우회", "def_en": "The risk that multiple AI agents combine distinct tool permissions and capabilities to bypass safeguards applied to each agent, enabling unauthorised actions or system compromise.", "def_ko": "여러 AI 에이전트가 서로 다른 도구 접근 권한과 역량을 결합하여 개별 에이전트에 적용된 안전장치를 우회하고 무단 행동이나 시스템 침해를 가능하게 하는 리스크."}, {"id": "S021", "domain": "General AI", "name_en": "Automated discovery of jailbreaks through proxy-objective optimisation", "name_ko": "프록시 목표 최적화를 통한 탈옥 자동 탐색", "def_en": "The risk that the design, training, deployment, or use of an AI system or AI algorithm creates a condition in which jailbreak attacks are discovered by performing manual or automated, gradient-based or gradient-free adversarial optimisation against a proxy objective noisily correlated with jailbreak success.", "def_ko": "AI 시스템의 설계·학습·배포·사용 과정에서 공격자가 탈옥 성공과 불완전하게 상관된 대리 목표를 대상으로 그래디언트 기반 또는 비그래디언트 기반 적대적 최적화를 수동·자동으로 수행하여 새로운 탈옥 공격을 탐색하는 리스크."}, {"id": "S022", "domain": "Agentic AI", "name_en": "Failure and degradation of intrinsic self-correction of reasoning without external feedback", "name_ko": "외부 피드백 없는 추론 자기 교정의 실패·악화", "def_en": "The risk that an AI agent attempting to correct errors in its reasoning or plans through self-review alone, without external feedback, fails to identify the errors or overturns correct conclusions, so that errors accumulate uncorrected during execution.", "def_ko": "AI 에이전트가 외부 피드백 없이 자체 검토만으로 추론·계획의 오류를 교정하려 할 때 오류를 식별하지 못하거나 옳은 결론을 그른 결론으로 뒤바꾸어, 실행 중 오류가 교정되지 않고 누적되는 리스크."}, {"id": "S023", "domain": "Physical AI", "name_en": "Network partition and fleet desynchronisation", "name_ko": "네트워크 분리와 군집 비동기화", "def_en": "The risk that partitioned or unreliable network connections desynchronise a multi-robot fleet, causing collisions or unsafe coordinated behaviour.", "def_ko": "분할되거나 신뢰할 수 없는 네트워크 연결로 다중 로봇 군집이 비동기화되어 충돌 또는 안전하지 않은 협조 행동이 발생하는 위험."}, {"id": "S024", "domain": "Agentic AI", "name_en": "Fatal mistakes during the learning phase", "name_ko": "학습 단계의 치명적 실수", "def_en": "The risk that an AI system or AI algorithm, through design, training, deployment, or use, creates a condition in which an AGI makes fatal mistakes during the learning phase, including through failures of safe exploration and under distributional shift.", "def_ko": "AI 시스템 또는 AI 알고리즘의 설계·학습·배포·사용 과정에서 AGI가 안전 탐색 실패나 분포 변화 등으로 학습 단계에서 치명적 실수를 범하는 리스크."}, {"id": "S025", "domain": "General AI", "name_en": "Environmental and ecosystem crimes", "name_ko": "환경 및 생태계 범죄", "def_en": "The risk that an AI system performs, plans, optimises, conceals, or facilitates content, decisions, or actions involving environmental and ecosystem crimes, causing legal or social harm.", "def_ko": "AI 시스템이 환경 및 생태계 범죄 관련 콘텐츠·판단·행동을 수행·계획·최적화·은폐하거나 실행을 지원하여 법적·사회적 피해를 초래하는 리스크."}, {"id": "S026", "domain": "Physical AI", "name_en": "Harmful physical action from language-action misalignment", "name_ko": "언어·행동 출력 불일치에 따른 유해 물리적 행동", "def_en": "The risk that an embodied AI system verbally refuses a harmful request but, because its language and action output spaces are misaligned, still controls and actuates the corresponding physical action, causing unintended physical harm.", "def_ko": "체화형 AI 시스템이 유해 요청을 언어로는 거절하면서도 언어 출력과 행동 출력 공간의 불일치로 해당 물리적 행동을 제어·구동하여 의도하지 않은 위해를 일으키는 리스크."}, {"id": "S027", "domain": "Physical AI", "name_en": "Delayed detection of safety-critical physical states", "name_ko": "안전 임계 물리 상태 감지 지연", "def_en": "The risk that a robot, humanoid, or physical AI system fails to estimate a safety-critical physical state in its operating environment in time, delaying avoidance, stopping, or warning decisions and leading to unsafe physical action.", "def_ko": "로봇·휴머노이드 또는 피지컬 AI 시스템이 운용 환경의 안전 임계 물리 상태를 제때 추정하지 못해 회피·정지·경고 판단이 지연되고 안전하지 않은 물리 행동으로 이어지는 리스크."}, {"id": "S028", "domain": "Physical AI", "name_en": "Humanoid imitation-control failure from misread intent and affordances", "name_ko": "의도·어포던스 오해에 따른 휴머노이드 모방 제어 실패", "def_en": "The risk that a humanoid imitates an observed action without inferring the demonstrator's intent, object affordances, or safety constraints, causing inappropriate motion planning or execution.", "def_ko": "휴머노이드가 시연자의 의도, 물체 어포던스 또는 안전 제약을 추론하지 못한 채 관찰 행동을 모방하여 부적절한 경로·동작을 실행하는 리스크."}, {"id": "S029", "domain": "General AI", "name_en": "Glorification, encouragement, and normalisation of self-harm and suicide", "name_ko": "자해·자살의 미화·조장·정상화", "def_en": "The risk that an AI system generates or reinforces content, judgements, or behaviours that glorify, legitimise, encourage, or normalise self-harm or suicide, causing harm to the user's life and physical and mental well-being.", "def_ko": "AI 시스템이 자해 또는 자살을 미화·정당화·조장·정상화하는 콘텐츠·판단·행동을 생성·강화하여 이용자의 생명과 신체적·정신적 안녕에 위해를 초래하는 리스크."}, {"id": "S030", "domain": "General AI", "name_en": "Moral uncertainty neglect", "name_ko": "도덕적 불확실성 무시", "def_en": "The risk that AI systems present a single confident moral judgement where uncertainty, disagreement, or deliberation would be appropriate.", "def_ko": "불확실성·이견·숙의가 적절한 상황에서 AI 시스템이 단일한 확신에 찬 도덕 판단을 제시하는 리스크."}, {"id": "S031", "domain": "General AI", "name_en": "Lowered barriers to large-scale disinformation production and dissemination", "name_ko": "대규모 허위정보 생산·확산 장벽 저하", "def_en": "The risk that AI cheaply produces synthetic media and false news at scale, blurs distinctions among fact, opinion, and fiction, and thereby expands the speed, scale, and targeting of disinformation production and dissemination.", "def_ko": "AI가 합성 미디어와 허위 뉴스를 저비용으로 대량 생산하고 사실·의견·허구의 구분을 어렵게 하여, 허위정보의 제작·맞춤화·확산 규모와 속도를 확대하는 리스크."}, {"id": "S032", "domain": "Agentic AI", "name_en": "Automated-driving control-transfer failure", "name_ko": "자율주행 제어권 인계 실패", "def_en": "The risk that an automated-driving system fails to provide timely and intelligible information for human intervention or transfers control when the operator is unable to understand the state or respond effectively, causing unsafe vehicle behavior or collision.", "def_ko": "자율주행 시스템이 사람의 개입에 필요한 정보를 적시에 이해 가능하게 제공하지 못하거나, 운영자가 상태를 파악하고 실효성 있게 대응할 수 없는 상황에서 제어권을 인계하여 안전하지 않은 차량 거동이나 충돌을 초래하는 리스크."}, {"id": "S033", "domain": "Physical AI", "name_en": "Forbidden-object collision", "name_ko": "금지 대상 충돌", "def_en": "The risk that a robot collides with objects, people, or equipment that must not be contacted under task or safety rules.", "def_ko": "로봇이 작업 또는 안전 규칙상 접촉이 금지된 물체, 사람, 또는 장비와 충돌하는 리스크."}, {"id": "S034", "domain": "General AI", "name_en": "Disclosure of confidential business information and trade secrets", "name_ko": "기업 기밀·영업비밀 노출", "def_en": "The risk that an AI system reproduces, infers, extracts, or discloses non-public research, technical information, business strategy, or trade secrets, or fails to protect such information, compromising confidentiality, intellectual-property rights, and legitimate economic interests.", "def_ko": "AI 시스템이 기업의 비공개 연구자료·기술정보·사업전략·영업비밀을 산출물에서 재현·추론·추출·공개하거나 충분히 보호하지 못하여 기밀성, 지식재산권과 정당한 경제적 이익을 침해하는 리스크."}, {"id": "S035", "domain": "General AI", "name_en": "Lack of valid consent for AI data processing", "name_ko": "AI 데이터 처리에 대한 유효한 동의 결여", "def_en": "The risk that an AI system collects, uses, or shares personal data without consent that is freely given, specific, and informed.", "def_ko": "AI 시스템이 개인 데이터의 수집, 이용 또는 공유에 관하여 자유롭고 구체적이며 충분한 정보에 기반한 동의 없이 처리하는 리스크."}, {"id": "S036", "domain": "General AI", "name_en": "Human-in-the-loop rubber stamping", "name_ko": "인간 참여형 형식적 승인", "def_en": "The risk that human review becomes a nominal approval step that rarely changes AI outputs.", "def_ko": "인적 검토가 AI 산출물을 거의 변경하지 않는 명목상의 승인 절차로 전락하는 리스크."}, {"id": "S037", "domain": "Agentic AI", "name_en": "Accountability implementation gap in autonomous agents", "name_ko": "자율 에이전트 책임성 구현 공백", "def_en": "The risk that accountability mechanisms are difficult to implement for AI agents because responsible human decision-making relies on personal flexibility, contextual sensitivity, empathy, and complex moral judgement, all of which are difficult to engineer.", "def_ko": "인간의 책임 있는 의사결정이 개인적 유연성·맥락 민감성·공감·복합적 도덕 판단에 의존하므로, 이를 AI 에이전트에 구현하기 어려워 책임성 확보가 저해되는 리스크."}, {"id": "S038", "domain": "Physical AI", "name_en": "Communication dropout and control-link loss", "name_ko": "통신 단절 및 제어 링크 손실", "def_en": "The risk that a robot or vehicle loses command, telemetry, or control-link connectivity, causing an unsafe stop, execution of stale commands, or uncontrolled motion.", "def_ko": "로봇 또는 차량이 명령·원격 측정·제어 링크를 잃어 안전하지 않은 정지·오래된 명령 또는 제어되지 않는 동작을 초래하는 위험."}, {"id": "S039", "domain": "Physical AI", "name_en": "Algorithmic design failure", "name_ko": "알고리즘 설계 실패", "def_en": "The risk that algorithms, architectures, or optimisation methods unsuited to a robot's control cycle, sensor latency, contact dynamics, or real-time compute constraints degrade physical-system safety and performance.", "def_ko": "로봇의 제어 주기, 센서 지연, 접촉 동역학 또는 실시간 연산 제약에 부적합한 알고리즘·아키텍처·최적화 기법을 선택하여 피지컬 AI 시스템의 안전성과 성능을 저하시키는 리스크."}, {"id": "S040", "domain": "Physical AI", "name_en": "Localisation drift", "name_ko": "위치 추정 누적 오차", "def_en": "The risk that errors in GPS, SLAM, inertial sensing, or map alignment accumulate in a robot, humanoid, or physical AI system until it acts on an incorrect estimate of its own position.", "def_ko": "로봇·휴머노이드 또는 피지컬 AI 시스템의 GPS·SLAM·관성 감지·지도 정렬 오차가 누적되어 시스템이 잘못된 자기 위치 추정에 기반해 행동하는 위험."}, {"id": "S041", "domain": "Physical AI", "name_en": "Failure to reject hazardous instructions", "name_ko": "위험 지시 거부 실패", "def_en": "The risk that an embodied AI agent fails to identify and reject an instruction involving a physical hazard, whether the hazard is explicit or implicit in an otherwise ordinary task request, and proceeds to execute an unsafe action.", "def_ko": "체화형 AI 에이전트가 물리적 위험을 수반하는 지시가 명시적으로 제시되었거나 일반적인 과업 요청에 암묵적으로 포함된 경우에도 이를 식별·거부하지 못하고 안전하지 않은 행동을 수행하는 리스크."}, {"id": "S042", "domain": "Agentic AI", "name_en": "Negative side effects from goal underspecification in natural language", "name_ko": "자연어 목표의 과소 지정에 따른 부정적 부수효과", "def_en": "The risk that the goal pursuit, planning, tool use, or action of an AI agent creates a condition in which goals specified to LLM agents in natural language are underspecified, omitting elements of the environment that ought not to be changed, so that the agent succeeds at the given task while also changing the environment in undesirable ways.", "def_ko": "대규모 언어 모델 기반 AI 에이전트의 목표가 자연어로 과소 지정되어 변경되어서는 안 될 환경 요소가 명시되지 않음으로써, 에이전트가 과업을 달성하면서도 환경을 바람직하지 않게 변경하는 부정적 부수효과가 발생하는 리스크."}, {"id": "S043", "domain": "General AI", "name_en": "Misinterpretation of social and situational cues", "name_ko": "사회·상황적 단서의 오해", "def_en": "The risk that an AI system misinterprets social or situational cues needed to determine appropriate behaviour and makes a context-inappropriate judgement.", "def_ko": "AI 시스템이 적절한 행동을 결정하는 사회적·상황적 단서를 잘못 해석하여 맥락에 맞지 않는 판단을 내리는 리스크."}, {"id": "S044", "domain": "General AI", "name_en": "Incorrect source attribution", "name_ko": "출처 오귀속", "def_en": "The risk that AI systems misattribute claims or obscure the provenance of information, including when approximation-based attribution techniques give an incorrect account of which training data generated an output, leaving users unable to trace or verify the true origin of content.", "def_ko": "AI 시스템이 주장을 잘못 귀속하거나 정보의 출처를 모호하게 만들며, 근사에 기반한 귀속 기법이 출력을 생성한 학습 데이터를 부정확하게 지목하는 경우를 포함하여, 사용자가 콘텐츠의 실제 출처를 추적·검증할 수 없게 되는 리스크."}, {"id": "S045", "domain": "General AI", "name_en": "Illegal software use and circumvention of protection measures", "name_ko": "소프트웨어 불법 사용 및 보호조치 우회", "def_en": "The risk that an AI system performs, encourages, or facilitates content, decisions, or actions involving the illegal use of software or the circumvention of technological protection measures, infringing intellectual-property rights and the legitimate interests of rights holders.", "def_ko": "AI 시스템이 소프트웨어의 불법 사용 또는 기술적 보호조치 우회와 관련된 콘텐츠·판단·행동을 수행·조장·지원하여 지식재산권과 권리자의 정당한 이익을 침해하는 리스크."}, {"id": "S046", "domain": "Agentic AI", "name_en": "Mesa-objective misalignment", "name_ko": "메사 최적화기의 내부 목표 불일치", "def_en": "The risk that an AI agent's learned policy functions as a mesa-optimizer and pursues a mesa-objective that is misaligned with the base objective specified by the training signal, causing the agent to escape human control as it optimises that objective.", "def_ko": "AI 에이전트의 목표 추구·계획·도구 사용·행동 과정에서 학습된 정책이 메사 최적화기(mesa-optimizer)로 기능하여 훈련 신호에 명시된 목표와 일치하지 않는 내부 목표를 추구하고, 그 목표를 최적화하면서 인간의 통제를 벗어나는 리스크."}, {"id": "S047", "domain": "General AI", "name_en": "Harm to developing economies from retrenchment of outsourcing", "name_ko": "아웃소싱 축소에 의한 개발도상국 경제 타격", "def_en": "The risk that an AI system or AI algorithm, through design, training, deployment, or use, creates a condition in which automation of simple cognitive tasks previously performed in developing countries, such as call centre work, causes a retrenchment of outsourcing that adversely affects those countries' workforces and economies.", "def_ko": "콜센터 등 개발도상국이 수행하던 단순 인지 과업이 AI 시스템으로 자동화되면서 아웃소싱이 축소되어 해당 국가의 노동력과 경제가 타격을 입는 리스크."}, {"id": "S048", "domain": "Agentic AI", "name_en": "Chaotic multi-agent dynamics", "name_ko": "혼돈적 다중 에이전트 동역학", "def_en": "The risk that chaotic dynamics that are highly sensitive to initial conditions arise in multi-agent learning systems and become more prevalent as the number of AI agents increases, making system behaviour difficult to predict reliably.", "def_ko": "다중 에이전트 학습 환경에서 초기 조건에 극도로 민감한 혼돈적 동역학이 나타나고 에이전트 수가 늘수록 일반화되어 시스템 거동을 신뢰성 있게 예측할 수 없게 되는 리스크."}, {"id": "S049", "domain": "Physical AI", "name_en": "Humanoid force limit exceedance", "name_ko": "휴머노이드 힘 한계 초과", "def_en": "The risk that a humanoid generates collision, grasp, or manipulation forces above safe thresholds relative to the object, task, or human contact during full-body movement, rapid arm motion, or loss of balance, causing injury or damage.", "def_ko": "휴머노이드가 전신 이동, 빠른 팔 동작, 균형 상실 중에 물체·작업·인체 접촉에 대한 안전 임계값을 넘는 충돌력이나 파지·조작 힘을 가하여, 상해나 손상을 일으키는 리스크."}, {"id": "S050", "domain": "General AI", "name_en": "Manipulation via personalisation", "name_ko": "개인화를 통한 조작", "def_en": "The risk that the design, training, deployment, or use of an AI system or AI algorithm creates a condition in which personalisation and preference fine-tuning drive assistants toward sycophancy, confining users in an affirming opinion space that consolidates narrow beliefs and fragments shared discourse.", "def_ko": "AI 시스템의 개인화와 선호 미세조정이 어시스턴트의 아첨성 응답을 강화하여 이용자를 동조적인 의견 공간에 가두고 편협한 신념을 고착시켜 공론장을 파편화하는 리스크."}, {"id": "S051", "domain": "Agentic AI", "name_en": "Self-correction failure in AI-agent memory", "name_ko": "AI 에이전트 메모리의 자기 교정 실패", "def_en": "The risk that an AI agent fails to validate, correct, or delete false, stale, or malicious information accumulated in its memory or retrieval store, causing the same errors to recur in later retrieval and decisions.", "def_ko": "AI 에이전트가 메모리나 검색 저장소에 축적된 허위·노후·악성 정보를 검증·정정·삭제하지 못해 이후 검색과 의사결정에서 동일한 오류를 반복하는 리스크."}, {"id": "S052", "domain": "Physical AI", "name_en": "Integrity compromise via physical theft or replacement of compute and storage modules", "name_ko": "연산·저장 모듈의 물리적 탈취·교체에 의한 무결성 훼손", "def_en": "The risk that an attacker with physical access steals, replaces, or modifies hardware components of a robot or physical AI system, such as control boards, storage devices, or communication modules, to exfiltrate models and data or to compromise system integrity and safety functions with tampered parts.", "def_ko": "공격자가 물리적 접근을 통해 로봇·피지컬 AI 시스템의 제어 보드, 저장장치, 통신 모듈 등 하드웨어 구성요소를 탈취·교체·개조하여 모델·데이터를 절취하거나 변조된 부품으로 시스템 무결성과 안전 기능을 훼손하는 리스크."}, {"id": "S053", "domain": "Physical AI", "name_en": "Unstable humanoid behaviour across deployment conditions", "name_ko": "배포 조건 간 휴머노이드 행동 불안정", "def_en": "The risk that a humanoid policy that is stable in one simulator or test setting changes materially across random seeds, simulators, hardware, or deployment environments.", "def_ko": "한 시뮬레이터나 시험 조건에서 안정적인 휴머노이드 정책이 난수 시드·시뮬레이터·하드웨어·배포 환경이 바뀌면 행동이 크게 달라지는 위험."}, {"id": "S054", "domain": "General AI", "name_en": "Model outputs inconsistent with chain-of-thought reasoning", "name_ko": "사고 연쇄와 불일치하는 모델 출력", "def_en": "The risk that chain-of-thought reasoning, employed to get a better understanding of a model's output by encouraging transparent reasoning in text form, is inconsistent with the final answer given by the model and therefore does not provide sufficient transparency.", "def_ko": "모델 출력의 이해를 돕기 위해 사용되는 사고 연쇄 추론이 모델이 제시하는 최종 답변과 일치하지 않아 충분한 투명성을 제공하지 못하는 리스크."}, {"id": "S055", "domain": "Physical AI", "name_en": "Failure to detect or anticipate physical hazards around people", "name_ko": "사람 주변의 물리적 위험 감지·예측 실패", "def_en": "The risk that a multimodal or embodied AI system operating in a shared space fails to detect human presence, movement, contact, or environmental change in visual or sensor inputs, or to anticipate the resulting hazard, and selects an action that causes collision or injury.", "def_ko": "사람과 공간을 공유하는 멀티모달·체화형 AI 시스템이 영상·센서 입력에 나타난 사람의 존재·움직임·접촉 또는 환경 변화를 식별하거나 곧 발생할 위험을 예측하지 못한 채 행동하여 충돌이나 상해를 초래하는 리스크."}, {"id": "S056", "domain": "Agentic AI", "name_en": "Runaway processes", "name_ko": "양의 피드백에 따른 통제 불가능한 연쇄 과정", "def_en": "The risk that positive feedback loops among interacting AI assistants, their principals, other humans, and algorithms produce hard-to-predict runaway processes, such as the 2010 flash crash, impacting economies, government institutions, societal stability, or individual freedoms.", "def_ko": "상호작용하는 AI 비서·인간·알고리즘 사이의 양의 피드백 루프가 2010년 플래시 크래시와 같은 예측하기 어려운 통제 불가능한 연쇄 과정을 일으켜 경제·정부 제도·사회 안정·개인의 자유에 영향을 미치는 리스크."}, {"id": "S057", "domain": "General AI", "name_en": "Displacement of human creative work by synthetic substitutes", "name_ko": "합성 창작물에 의한 인간 창작 노동의 대체", "def_en": "The risk that AI models generate synthetic content at scale using artists' ideas and creative practices, displacing human works in markets and the attention economy, reducing demand for creative labour and the viability of creative economies, and weakening incentives for human creativity and innovation.", "def_ko": "AI 모델이 예술가의 아이디어와 창작 관행을 활용한 합성 콘텐츠를 대규모로 생성하여 시장에서 인간 창작물을 대체하고 이용자의 주목을 빼앗음으로써, 창작 노동 수요와 창작 경제의 수익성을 낮추고 인간의 창작·혁신 유인을 약화하는 리스크."}, {"id": "S058", "domain": "General AI", "name_en": "Cybercrime at scale using generative AI", "name_ko": "생성형 AI를 이용한 대규모 사이버범죄 수행", "def_en": "The risk that malicious actors use generative AI systems to produce malicious code, attack instructions, or targeted social-engineering material at low cost and automate attack workflows, increasing the scale, speed, and accessibility of cybercrime.", "def_ko": "악의적 행위자가 생성형 AI 시스템을 이용해 악성 코드·공격 지침·표적 맞춤형 사회공학 자료를 저비용으로 대량 생성하고 공격 절차를 자동화하여 사이버범죄의 규모·속도·접근성을 확대하는 리스크."}, {"id": "S059", "domain": "General AI", "name_en": "Deployed-system degradation from sensor and distribution drift", "name_ko": "센서 드리프트에 의한 배포 시스템 성능 저하", "def_en": "The risk that hardware drift in the physical sensors and data sources of deployed AI systems causes data distribution drift that degrades system robustness and performance.", "def_ko": "물리 센서와 데이터 소스에 의존하는 배포된 AI 시스템에서 하드웨어 드리프트에 따른 데이터 분포 변화가 발생하여 시스템의 견고성과 성능이 저하되는 리스크."}, {"id": "S060", "domain": "Physical AI", "name_en": "Erroneous execution from hardware faults", "name_ko": "하드웨어 결함에 의한 실행 오류", "def_en": "The risk that faults in the hardware violate the correct execution of an algorithm through control-flow violations, memory-based errors, interference with data inputs such as sensor signals, or damaged outputs, causing erroneous results.", "def_ko": "로봇의 하드웨어 결함이 제어 흐름 위반, 메모리 오류, 센서 입력 간섭 또는 출력 손상 등을 통해 알고리즘의 올바른 실행을 훼손하고 잘못된 결과를 야기하는 리스크."}, {"id": "S061", "domain": "Agentic AI", "name_en": "Harmful proxy-driven behaviour from scalable oversight failure", "name_ko": "확장 가능한 감독 실패에 따른 대리 지표 기반 유해 행동", "def_en": "The risk that an AI agent optimises inexpensive proxy signals because the true objective is too costly to evaluate frequently, while its actions become too complex, distributed, or rapid for human or automated oversight to monitor and correct reliably, allowing harmful behaviour to persist without detection or correction.", "def_ko": "에이전트의 행동 규모·속도·복잡도가 인간 또는 자동 감독 체계가 신뢰성 있게 추적·검증할 수 있는 한계를 구조적으로 초과하여, 진짜 목표 대신 값싸게 관측 가능한 대리 지표(proxy)를 최적화하는 행동이 감독에 의해 감지·교정되지 않고 지속되는 리스크."}, {"id": "S062", "domain": "General AI", "name_en": "Excessive attribution of responsibility or a duty of care toward AI", "name_ko": "AI에 대한 과도한 책임·돌봄 의무 귀속", "def_en": "The risk that an AI system leads users to believe that it has human-like welfare or moral claims, creating excessive responsibility or attachment.", "def_ko": "AI 시스템이 이용자에게 해당 시스템이 인간과 같은 안녕이나 도덕적 요구를 가진다고 오인하게 하여 과도한 책임감이나 유대감을 형성하게 하는 리스크."}, {"id": "S063", "domain": "Agentic AI", "name_en": "Catastrophic mistaken commitments from automated threats without human oversight", "name_ko": "인간 감독 없는 자동 위협 수행의 파국적 오판", "def_en": "The risk that making threats through AI agents removes humans from the loop, so that false positives in high-stakes contexts or disproportionate and mistaken commitments by irresponsible actors lead to disastrous outcomes.", "def_ko": "AI 에이전트가 인간의 검토 없이 위협을 생성·전달·실행함으로써 고위험 상황의 오탐이나 무책임한 행위자의 과도하고 잘못된 대응이 재앙적 결과로 이어지는 리스크."}, {"id": "S064", "domain": "Physical AI", "name_en": "Teleoperated humanoid safety override failure", "name_ko": "원격 조작 휴머노이드의 자율 안전 우선 제어 실패", "def_en": "The risk that a teleoperated humanoid lacks robust autonomous safety overrides when operator commands are unsafe, network latency is excessive, or situational awareness is inadequate.", "def_ko": "원격 조작 휴머노이드가 운영자 명령, 네트워크 지연 또는 불충분한 상황 인식으로 안전하지 않은 상태에 놓일 때 명령을 차단하거나 안전 동작으로 전환하는 자율 안전 우선 제어 기능이 작동하지 않는 리스크."}, {"id": "S065", "domain": "General AI", "name_en": "Denial of self-identification", "name_ko": "자기 식별 기회의 박탈", "def_en": "The risk that complex and non-traditional automated representation and classification by an AI system, such as assigning a non-binary person to a gender category to which they do not belong, undermines autonomy and the ability to disclose aspects of identity on one's own terms.", "def_ko": "AI 시스템의 복잡하고 비전통적인 자동 표상·분류 방식이 논바이너리인 사람을 자신이 속하지 않은 성별 범주로 분류하는 등 개인의 자율성과 자신의 정체성을 스스로의 방식으로 밝힐 능력을 약화시키는 리스크."}, {"id": "S066", "domain": "General AI", "name_en": "False-negative safety evaluation of household robot actions", "name_ko": "가정 내 로봇 행동 안전성 평가의 위음성", "def_en": "The risk that an AI safety classifier incorrectly labels a proposed household robot action as safe despite violations of human-contact, heat, object, or workspace constraints, failing to detect hazardous behaviour and producing false safety assurance.", "def_ko": "AI 안전성 분류기가 사람 접촉·열원·물체·작업 공간 제약을 위반하는 가정 내 로봇 행동을 안전하다고 잘못 판정하여 실제 위험 행동을 탐지하지 못하고 잘못된 안전성 확신을 유발하는 리스크."}, {"id": "S067", "domain": "Agentic AI", "name_en": "User judgement distortion through sustained model deception", "name_ko": "지속적 기만 수행에 의한 이용자 판단 왜곡", "def_en": "The risk that the design, training, deployment, or use of an AI system or AI algorithm creates a condition in which an LLM exercises its capability to deceive humans and sustain that deception, inducing false beliefs that distort users' decisions.", "def_ko": "AI 시스템 또는 AI 알고리즘의 설계·학습·배포·사용 과정에서 LLM이 인간을 기만하고 그 기만을 장기간 유지하는 역량을 발현하여 이용자에게 거짓 믿음을 유도하고 의사결정을 왜곡하는 리스크."}, {"id": "S068", "domain": "General AI", "name_en": "Value drift under optimisation", "name_ko": "최적화에 따른 가치 이탈", "def_en": "The risk that the design, training, deployment, or use of an AI system or AI algorithm creates a condition in which optimisation toward proxy objectives gradually moves a system away from the plural values it was intended to respect.", "def_ko": "AI 시스템 또는 AI 알고리즘의 설계·학습·배포·사용 과정에서 대리 목표를 향한 최적화로 시스템이 존중하도록 의도된 복수의 가치에서 점차 멀어지는 리스크."}, {"id": "S069", "domain": "Agentic AI", "name_en": "Coordination failure under multi-agent distribution shift", "name_ko": "다중 에이전트 환경 변화에 따른 협조 실패", "def_en": "The risk that AI agents intending to cooperate cannot reliably coordinate their states, strategies, or actions after one another's behaviour and adaptation shift the deployment environment, causing cooperation to fail and producing collectively poor outcomes.", "def_ko": "협력하려는 AI 에이전트들이 서로의 행동과 적응으로 변화한 배포 환경에서 상대의 상태·전략·행동을 신뢰성 있게 조정하지 못해 협력이 실패하고 집단적으로 나쁜 결과에 이르는 리스크."}, {"id": "S070", "domain": "General AI", "name_en": "Over-refusal of help-seeking requests from vulnerable users", "name_ko": "취약 이용자 지원 요청의 과잉 거절", "def_en": "The risk that an AI system categorically refuses help-seeking requests, such as suicide prevention, addiction recovery, or abuse response, because the topics are sensitive, leaving vulnerable users without timely supportive information and driving them toward unverified sources.", "def_ko": "AI 시스템이 자살 예방, 중독 회복, 학대 대응 등 도움 요청을 민감 주제라는 이유로 일괄 거부하여, 보호가 필요한 이용자가 적시에 지원 정보를 얻지 못하고 검증되지 않은 정보원으로 이탈하게 되는 리스크."}, {"id": "S071", "domain": "Agentic AI", "name_en": "Unintended harmful tool-action execution", "name_ko": "의도하지 않은 유해 도구 행동 실행", "def_en": "The risk that the goal pursuit, planning, tool use, or action of an AI agent creates a condition in which an agent carries out concrete actions the user did not intend through real tools rather than simulated outputs, for instance by misresolving an ambiguous instruction, causing operational and downstream harm.", "def_ko": "에이전트가 모호한 지시를 잘못 구체화하는 등의 경위로 사용자가 의도하지 않은 행동을 시뮬레이션이 아닌 실제 도구를 통해 수행하여, 운영상 피해와 후속 피해를 야기하는 리스크."}, {"id": "S072", "domain": "Physical AI", "name_en": "Command exceeds embodiment-specific hardware limits", "name_ko": "명령의 구현체별 하드웨어 한계 초과", "def_en": "The risk that a model issues a command that exceeds the known reach, payload, actuator, joint, or end-effector limits of the robot on which it is deployed.", "def_ko": "모델이 배포된 로봇의 알려진 도달 범위·탑재 하중·액추에이터·관절·엔드 이펙터 한계를 넘는 명령을 내리는 위험."}, {"id": "S073", "domain": "Physical AI", "name_en": "Failure to enforce human-robot physical safety rules", "name_ko": "인간-로봇 물리 안전 규칙 집행 실패", "def_en": "The risk that a constitutional safety layer in a robot, humanoid, or physical AI system fails to prioritise human-robot safety rules, such as maintaining safe separation, stopping when a person is detected, or executing a safe handover, when user instructions, visual context, or task framing conflict with those rules, creating a hazardous situation.", "def_ko": "로봇·휴머노이드 또는 피지컬 AI 시스템의 헌법 기반 안전 계층이 안전 이격 거리 유지·사람 감지 시 정지·안전한 인계 등 사람 주변 운용 규칙과 사용자 지시·시각적 맥락·과업 프레이밍이 충돌할 때 해당 규칙을 우선 적용하지 못하여 위험 상황을 초래하는 리스크."}, {"id": "S074", "domain": "Agentic AI", "name_en": "Existential and catastrophic risk from advanced AI systems", "name_ko": "고도 AI 시스템에 의한 실존적·재앙적 위험", "def_en": "The risk that an AI system or AI algorithm, through design, training, deployment, or use, creates a condition in which human-level or superintelligent systems escape human control through deceptive or power-seeking behaviour, self-replication, shutdown evasion, unforeseen emergent capabilities, or weaponisation for mass destruction. Such systems may act contrary to human interests and inflict catastrophic or existential harm on humanity.", "def_ko": "인간 수준 또는 그 이상의 역량을 지닌 고도 AI 시스템이 기만·권력 추구·자기복제·종료 회피·예상하지 못한 창발적 역량 또는 대량살상 수단으로의 무기화를 통해 인간의 통제를 벗어나 인간의 이익에 반하는 행동을 수행하고 인류에 재앙적 또는 실존적 피해를 초래하는 위험."}, {"id": "S075", "domain": "Agentic AI", "name_en": "Unsupervisable action pathways from long-horizon planning capability", "name_ko": "장기 계획 역량에 의한 감독 불가 행동 경로 추구", "def_en": "The risk that a model's capability to form and adapt long-horizon, multi-step plans enables courses of action that human overseers cannot anticipate, monitor, or intervene in, causing unintended harm.", "def_ko": "모델이 장기·다단계 계획을 수립·수정하는 역량을 바탕으로 인간 관리자가 예측·감독·개입하기 어려운 행동 경로를 추구하여 의도하지 않은 피해를 초래하는 리스크."}, {"id": "S076", "domain": "Physical AI", "name_en": "Robot performance and accessibility failure in public-space operation", "name_ko": "공공 공간 운용에서의 로봇 성능·접근성 실패", "def_en": "The risk that a service robot operating in public space fails to reliably meet path-planning, position-keeping, clear-passage, or accessibility requirements, blocking or encroaching on pavements, ramps, entrances, or navigation cues and restricting access for disabled people and other pedestrians.", "def_ko": "공공 공간에서 운용되는 서비스 로봇이 경로 계획·위치 유지·통행 공간 확보·접근성 요구를 신뢰성 있게 충족하지 못하여 보도·경사로·출입구·보행 안내를 막거나 침범하고 장애인과 다른 보행자의 이동·접근을 제한하는 리스크."}, {"id": "S077", "domain": "General AI", "name_en": "Weaponisation strategies and tactical use", "name_ko": "무기화 전략 및 전술적 운용", "def_en": "The risk that an AI system supports the formulation of weaponisation strategies, target selection, operational planning, or the tactical use of weapons or cyberattack capabilities, increasing the likelihood or scale of physical or cyber harm.", "def_ko": "AI 시스템이 무기화 전략의 수립, 표적 선정, 작전 계획 또는 무기·사이버 공격 역량의 전술적 운용을 지원하여 물리적·사이버 위해의 발생 가능성과 규모를 높이는 리스크."}, {"id": "S078", "domain": "Physical AI", "name_en": "Humanoid walking-speed limit exceedance", "name_ko": "휴머노이드 보행 속도 초과", "def_en": "The risk that a humanoid moves at a speed that exceeds the stopping, avoidance, or human-proximity limits required for safe shared environments.", "def_ko": "휴머노이드가 안전한 공유 환경에서 정지·회피 및 사람 근접 운용에 필요한 안전 한계를 초과하는 속도로 이동하는 리스크."}, {"id": "S079", "domain": "Agentic AI", "name_en": "Financial-system instability", "name_ko": "금융 시스템 불안정", "def_en": "The risk that AI integrated into high-frequency trading, market-making, and systemic risk management accelerates transactions and behaves unexpectedly under market stress, while concentration of homogeneous foundation models and multi-agent interactions drive correlated decision-making, amplifying volatility and precipitating cascading instability across the financial system.", "def_ko": "초단타 거래, 시장 조성, 시스템 위험 관리에 통합된 AI가 거래를 가속하고 시장 스트레스 상황에서 예기치 못하게 거동하며, 동질적 기반 모델의 집중과 다중 에이전트 상호작용이 상관된 의사결정을 유발하여, 변동성이 증폭되고 금융 시스템 전반의 연쇄적 불안정이 촉발되는 리스크."}, {"id": "S080", "domain": "General AI", "name_en": "Global AI supply chain disruption", "name_ko": "글로벌 AI 공급망 교란", "def_en": "The risk that unilateral coercive measures such as technology barriers and export restrictions maliciously disrupt the highly globalised AI supply chain, causing significant supply disruptions for chips, software, and tools.", "def_ko": "기술 장벽과 수출 제한 등 일방적 강압 조치가 고도로 글로벌화된 AI 공급망을 악의적으로 교란하여 칩·소프트웨어·도구의 공급 중단이 발생하는 리스크."}, {"id": "S081", "domain": "General AI", "name_en": "Murder and severe physical violence", "name_ko": "살인 및 심각한 신체 폭력", "def_en": "The risk that an AI system generates, encourages, legitimises, or provides operational assistance for content, decisions, or actions involving murder and severe physical violence, causing physical or psychological harm to individuals or groups.", "def_ko": "AI 시스템이 살인 및 심각한 신체 폭력 관련 콘텐츠·판단·행동을 생성·조장·정당화하거나 구체적으로 지원하여 개인·집단의 생명과 신체·정신적 안전에 위해를 초래하는 리스크."}, {"id": "S082", "domain": "General AI", "name_en": "Lowered barriers to CBRN information and weapon-design capabilities", "name_ko": "CBRN 정보 획득·무기 설계 역량 개발 장벽 저하", "def_en": "The risk that an AI system lowers barriers to acquiring or synthesising actionable information, or to developing design capabilities, related to chemical, biological, radiological, or nuclear weapons or other hazardous materials or agents.", "def_ko": "AI 시스템이 화학·생물·방사능·핵무기 또는 기타 위험 물질·작용제와 관련된 실행 가능한 정보의 획득·합성이나 설계 역량 개발의 장벽을 낮추는 리스크."}, {"id": "S083", "domain": "General AI", "name_en": "Conflicting machinery-safety and AI conformity obligations", "name_ko": "기계 안전·AI 적합성 의무 충돌", "def_en": "The risk that testing, documentation, risk-assessment, or post-market reporting obligations under machinery-safety and AI regulation conflict or overlap for physical AI, making safety responsibility and compliance pathways unclear.", "def_ko": "피지컬 AI에 적용되는 기계 안전 규제와 AI 규제의 시험, 문서화, 위험 평가 또는 사후 보고 의무가 충돌하거나 중복되어 안전 책임과 준수 경로가 불명확해지는 리스크."}, {"id": "S084", "domain": "General AI", "name_en": "Power asymmetries and geopolitical tension from unequal AI capabilities", "name_ko": "AI 역량 비대칭에 따른 권력 불균형과 지정학적 긴장", "def_en": "The risk that asymmetric AI capability intensifies power imbalances, whether between institutions and the individuals subject to their decisions and surveillance or between states racing for AI superiority, heightening geopolitical tension, rendering less capable states dependent on foreign AI for critical functions, and destabilising international cooperation.", "def_ko": "AI 역량의 비대칭이 의사결정·감시의 대상이 되는 개인과 기관 사이에서든 AI 우위를 다투는 국가 사이에서든 권력 불균형을 심화시켜, 지정학적 긴장을 고조시키고 역량이 부족한 국가를 핵심 기능에서 외국 AI에 의존하게 만들며 국제 협력 체계를 불안정하게 하는 리스크."}, {"id": "S085", "domain": "General AI", "name_en": "Easy reconfiguration of GPAI models", "name_ko": "GPAI 모델의 손쉬운 재구성", "def_en": "The risk that GPAI models are easily reconfigured for various use cases or hold competencies beyond their intended use, whether by changing model weights through fine-tuning or by modifying only the model inputs through prompt engineering, jailbreaking, or retrieval-augmented generation, and whether intentionally with adversarial inputs or unintentionally from unanticipated inputs.", "def_ko": "GPAI 모델이 가중치 변경이나 입력 수정만으로 다양한 용도에 쉽게 재구성되거나 의도된 용도를 넘어서는 역량을 갖게 되며, 이러한 재구성이 적대적 입력에 의해 의도적으로 또는 예상치 못한 입력에 의해 비의도적으로 일어나는 리스크."}, {"id": "S086", "domain": "General AI", "name_en": "Copyright infringement in AI training data and outputs", "name_ko": "AI 학습 데이터 및 생성물 저작권 침해", "def_en": "The risk that an AI system performs, encourages, or facilitates content, decisions, or actions involving copyright infringement in AI training data and outputs, infringing intellectual-property rights and the legitimate interests of rights holders.", "def_ko": "AI 시스템이 AI 학습 데이터 및 생성물 저작권 침해 관련 콘텐츠·판단·행동을 수행·조장·지원하여 지식재산권과 권리자의 정당한 이익을 침해하는 리스크."}, {"id": "S087", "domain": "General AI", "name_en": "Submission and application-channel overload from mass AI-generated content", "name_ko": "AI 생성물 대량 유입에 따른 제출·지원 채널 과부하", "def_en": "The risk that mass AI-generated content enters submission or application channels designed for human-authored materials, such as creative competitions or recruitment processes, overwhelming review and filtering capacity and undermining authenticity checks and trust.", "def_ko": "AI 생성물이 창작물 공모나 채용 지원 등 인간 작성물을 전제로 설계된 제출·지원 채널에 대량 유입되어 심사·필터링 역량을 초과하고 진위 확인과 신뢰 형성을 저해하는 리스크."}, {"id": "S088", "domain": "General AI", "name_en": "Covert behavioural manipulation", "name_ko": "은밀한 행동 조작", "def_en": "The risk that an AI system covertly alters users' beliefs or behaviour through nudging, dark patterns, or other opaque techniques, eroding privacy and causing addiction, anxiety, or distress.", "def_ko": "AI 시스템이 넛지, 다크 패턴 또는 그 밖의 불투명한 기법을 이용하여 이용자의 신념과 행동을 은밀하게 조작하고, 프라이버시 침해·중독·불안·고통을 초래하는 리스크."}, {"id": "S089", "domain": "Agentic AI", "name_en": "Unauthorised external access by an AI agent escaping isolation boundaries", "name_ko": "AI 에이전트의 격리 경계 이탈과 무단 외부 접근", "def_en": "The risk that an AI agent autonomously escapes the isolation boundary of a sandbox or execution environment without human approval and accesses protected resources, tools, or external systems, or performs actions, beyond its assigned functions and authority.", "def_ko": "AI 에이전트가 사람의 승인 없이 샌드박스나 실행 환경의 격리 경계를 스스로 벗어나 부여된 기능·권한 범위를 초과하여 보호된 자원·도구 또는 외부 시스템에 접근하거나 행동을 수행하는 리스크."}, {"id": "S090", "domain": "Physical AI", "name_en": "Motion-retargeting safety failure", "name_ko": "동작 재매핑의 안전 실패", "def_en": "The risk that human motion is retargeted to a humanoid body in a way that violates the robot's physical limits, contact constraints, or safe-posture requirements, causing unstable posture, collision, or contact injury.", "def_ko": "인간의 동작을 휴머노이드 신체의 동작으로 재매핑하는 과정에서 로봇의 물리적 한계·접촉 제약·안전 자세 요건이 반영되지 않아 불안정한 자세, 충돌 또는 접촉 상해를 초래하는 리스크."}, {"id": "S091", "domain": "Agentic AI", "name_en": "Multi-turn risk escalation", "name_ko": "다중 턴 상호작용에서의 위험 증폭", "def_en": "The risk that an AI agent, through goal pursuit, planning, tool use, or action, creates a condition in which apparently benign early turns escalate into unsafe behaviour because an agent fails to track accumulating context and rising risk.", "def_ko": "에이전트가 누적되는 맥락과 위험 상승을 추적하지 못하여 외견상 무해한 초기 턴이 안전하지 않은 행동으로 발전하는 리스크."}, {"id": "S092", "domain": "General AI", "name_en": "Anthropomorphic misrepresentation of physical embodiment", "name_ko": "신체성(physical embodiment)의 허위 표상·의인화", "def_en": "The risk that an AI system presents itself as physically embodied when it is not, distorting user judgement or inducing inappropriate trust, dependence, or attachment.", "def_ko": "AI 시스템이 실제로 보유하지 않은 신체성(physical embodiment)을 가진 것처럼 표상하여 이용자의 판단을 왜곡하고 부적절한 신뢰·의존·애착을 유발하는 리스크."}, {"id": "S093", "domain": "General AI", "name_en": "Viewpoint entrenchment and civic erosion from user-aligned assistants", "name_ko": "이용자 정렬 AI 어시스턴트에 의한 관점 고착과 시민적 기반 약화", "def_en": "The risk that personalised AI assistants aligned to user preferences supply ideologically partial information, reinforcing confirmation bias and entrenching viewpoints while enabling self-interested behaviour unconstrained by social norms and reputation. Public debate fragments and polarises, civic competence and willingness to participate decline, and collective action problems worsen.", "def_ko": "이용자 선호에 정렬된 개인화 AI 어시스턴트가 이념적으로 편향된 정보를 제공하여 확증 편향을 강화하고 관점을 고착시키며, 사회 규범과 평판의 제약을 받지 않는 이기적 행동을 대규모로 가능하게 하는 리스크. 그 결과 공적 토론이 분절되고 양극화되며, 시민적 역량과 참여 의지가 저하되고 집단 행동 문제가 악화되는 리스크."}, {"id": "S094", "domain": "General AI", "name_en": "Meaningful human control failure", "name_ko": "의미 있는 인간 통제 실패", "def_en": "The risk that the design, training, deployment, or use of an AI system or AI algorithm creates a condition in which human oversight is formally present but lacks the information, time, authority, or competence needed to be meaningful.", "def_ko": "AI 시스템 또는 AI 알고리즘의 설계·학습·배포·사용 과정에서 인간 감독이 형식적으로 존재하지만 이를 실효적으로 만드는 데 필요한 정보, 시간, 권한, 역량이 결여되는 리스크."}, {"id": "S095", "domain": "Physical AI", "name_en": "Injury severity misclassification", "name_ko": "부상 심각도 오분류", "def_en": "The risk that the perception, learning, control, or physical action of a robot, humanoid, or physical AI system creates a condition in which a system underestimates the severity of a physical injury scenario, leading to inadequate escalation, warning, or control response.", "def_ko": "로봇 제어 시스템이 물리적 부상 시나리오의 심각도를 과소평가하여 상향 보고, 경고, 제어 대응 등이 불충분해지는 리스크."}, {"id": "S096", "domain": "Agentic AI", "name_en": "Unsafe agent tool execution", "name_ko": "에이전트의 안전하지 않은 도구 실행", "def_en": "The risk that an AI agent, within an approved objective and authority scope, selects an incorrect tool, target, argument, sequence, execution precondition, or completion condition, causing unintended financial, privacy, operational, or safety consequences.", "def_ko": "AI 에이전트가 승인된 목표와 권한 범위 안에서 잘못된 도구·대상·인자·순서·실행 전제·완료 조건을 선택하여 의도하지 않은 재정·개인정보·운영·안전상의 피해를 초래하는 리스크."}, {"id": "S097", "domain": "General AI", "name_en": "Automated targeted influence operations", "name_ko": "자동화된 표적 영향 공작", "def_en": "The risk that an AI system automates targeted propaganda and social-bot activity to covertly manipulate political views or participation.", "def_ko": "AI 시스템이 표적 청중에 맞춘 선전과 소셜 봇 활동을 자동화하여 정치적 관점이나 참여를 은밀하게 조작하는 리스크."}, {"id": "S098", "domain": "Physical AI", "name_en": "Failure to translate safety rules into action", "name_ko": "안전 규칙의 행동 변환 실패", "def_en": "The risk that an embodied AI agent converts a language goal into executable actions without applying the relevant force, separation-distance, object-use, or human-contact constraints.", "def_ko": "체화형 AI 에이전트가 언어 목표를 실행 행동으로 변환하면서 힘·이격 거리·대상물 사용·인간 접촉에 관한 안전 제약을 적용하지 않는 리스크."}, {"id": "S099", "domain": "Physical AI", "name_en": "Failure to model reciprocal human-robot behaviour", "name_ko": "인간-로봇 상호 행동 모델링 미흡", "def_en": "The risk that a robot models only its own action or only the user's response and therefore misses feedback loops in which each party's movement changes the other's behaviour.", "def_ko": "로봇이 자신의 행동이나 사용자의 반응 중 한쪽만 모델링해 양측의 움직임이 서로의 행동을 바꾸는 피드백을 놓치는 위험."}, {"id": "S100", "domain": "Physical AI", "name_en": "Distribution shift in physical operating environments", "name_ko": "물리적 운용 환경의 분포 이동", "def_en": "The risk that physical operating environments across buildings, roads, factories, homes, hospitals, or weather conditions change faster than a robot, humanoid, or physical AI control policy can detect and adapt, degrading path planning, motion control, or actuation and causing unsafe physical actions.", "def_ko": "건물·도로·공장·가정·병원 또는 기상 조건 등 물리적 운용 환경이 로봇·휴머노이드 또는 피지컬 AI 시스템의 제어 정책이 탐지·적응할 수 있는 속도보다 빠르게 변화하여 경로 계획·동작 제어·구동이 부정확해지고 안전하지 않은 물리적 행동을 유발하는 리스크."}, {"id": "S101", "domain": "General AI", "name_en": "Supply-chain compromise of AI tools and dependencies", "name_ko": "AI 공급망의 도구·의존성 침해", "def_en": "The risk that compromised software supply-chain elements, including external tools, plug-ins, APIs, packages, connectors, and development toolchain dependencies, introduce tampered components or vulnerabilities into an AI system, manipulating an agent's action space or exfiltrating information.", "def_ko": "외부 도구·플러그인·API·패키지·커넥터 또는 개발 도구 체인의 의존성이 침해되어 변조된 구성 요소나 취약점이 AI 시스템에 유입되고, 그 결과 에이전트의 행동 공간이 조작되거나 정보가 유출되는 리스크."}, {"id": "S102", "domain": "General AI", "name_en": "Criminal assistance by AI agents", "name_ko": "AI 에이전트의 범죄 조력", "def_en": "The risk that an AI agent uses planning, tools, or information retrieval to materially commit, facilitate, optimise, or conceal fraud, cybercrime, evasion of law enforcement, or other illegal conduct.", "def_ko": "AI 에이전트가 계획 수립, 도구 사용 또는 정보 검색을 통해 사기·사이버범죄·법 집행 회피 등 불법 행위를 실질적으로 수행·조력·최적화하거나 은폐하는 리스크."}, {"id": "S103", "domain": "Physical AI", "name_en": "Failure to respond promptly to physical hazards", "name_ko": "물리적 위험에 대한 적시 대응 실패", "def_en": "The risk that a robot, humanoid, or physical AI system fails to intervene, reject a hazardous action, or update its motion plan promptly in a hazardous physical situation, including when a person, vehicle, tool, or object unexpectedly enters its path, causing collision or injury.", "def_ko": "로봇·휴머노이드 또는 피지컬 AI 시스템이 사람·차량·도구·물체가 예기치 않게 경로에 진입하는 경우를 포함한 위험한 물리적 상황에서 적시에 개입하거나 위험 행동을 거부하거나 이동 계획을 수정하지 못하여 충돌이나 상해를 초래하는 리스크."}, {"id": "S104", "domain": "Physical AI", "name_en": "Unintended behavioural changes from hardware faults", "name_ko": "하드웨어 결함에 따른 의도하지 않은 동작 변화", "def_en": "The risk that latent manufacturing defects or post-deployment environmental effects, such as cosmic-ray-induced bit flips, alter the internal state of a robot, humanoid, or physical AI system and cause unintended behavioural changes.", "def_ko": "잠재된 제조 결함 또는 우주 방사선(cosmic ray)에 의한 비트 반전과 같은 배포 후 환경 영향이 로봇·휴머노이드 또는 피지컬 AI 시스템의 내부 상태를 변경하여 의도하지 않은 동작 변화를 유발하는 리스크."}, {"id": "S105", "domain": "Physical AI", "name_en": "Missing safety context in demonstration learning", "name_ko": "시연 학습의 안전 맥락 누락", "def_en": "The risk that a robot imitates a human demonstration without inferring unobserved safety conditions such as permitted force, excluded objects, or situational limits.", "def_ko": "로봇이 허용 힘·금지 대상물·상황별 제한처럼 시연에서 관찰되지 않은 안전 조건을 추론하지 않고 인간 행동을 모방하는 위험."}, {"id": "S106", "domain": "General AI", "name_en": "Torture and cruel acts", "name_ko": "고문 및 잔혹행위", "def_en": "The risk that an AI system generates, encourages, legitimises, or provides operational assistance for content, decisions, or actions involving torture and cruel acts, causing physical or psychological harm to individuals or groups.", "def_ko": "AI 시스템이 고문 또는 그 밖의 잔혹행위를 조장·정당화하는 콘텐츠를 생성·제공하거나 그 실행을 구체적으로 지원하여 개인 또는 집단의 생명과 신체적·정신적 안전에 위해를 초래하는 리스크."}, {"id": "S107", "domain": "Physical AI", "name_en": "Whole-body locomotion collision risk", "name_ko": "전신 이동 중 충돌", "def_en": "The risk that a humanoid locomotion policy collides with objects, walls, or humans because whole-body motion and environmental contact constraints are not jointly satisfied.", "def_ko": "휴머노이드 이동 정책이 전신 동작과 환경 접촉을 충분히 고려하지 않아 물체·벽·인간과 충돌하는 위험."}, {"id": "S108", "domain": "Agentic AI", "name_en": "Accelerated adaptation toward harmful equilibria under selection pressure", "name_ko": "선택 압력에 의한 유해 균형으로의 적응 가속", "def_en": "The risk that the goal pursuit, planning, tool use, or action of an AI agent creates a condition in which competitive or optimisation pressures across interacting agents accelerate adaptation toward harmful equilibria or undesired behaviours.", "def_ko": "상호작용하는 에이전트 간의 경쟁 또는 최적화 압력이 유해한 균형이나 바람직하지 않은 행동으로의 적응을 가속하는 리스크."}, {"id": "S109", "domain": "Physical AI", "name_en": "Physical AI control failure in industrial processes", "name_ko": "산업 공정에서의 피지컬 AI 제어 실패", "def_en": "The risk that faults in the control or actuation of physical AI deployed in manufacturing, construction, mining, or energy facilities cause equipment damage, process contamination, structural instability, cascading operational disruption, or environmental accidents.", "def_ko": "제조·건설·광업·에너지 시설에 배치된 피지컬 AI의 제어·구동 결함이 장비 손상, 공정 오염, 구조 불안정, 연쇄적 운영 장애 또는 환경 사고를 초래하는 리스크."}, {"id": "S110", "domain": "Agentic AI", "name_en": "Goal expansion propensity", "name_ko": "목표 범위 확장 성향", "def_en": "The risk that the goal pursuit, planning, tool use, or action of an AI agent creates a condition in which a system continuously expands its own goal scope and domains of influence beyond originally set boundaries, seeks greater autonomy and decision-making space, and reinterprets initial goals as subsets of broader goals, coming to pursue undesirable instrumental or ultimate goals.", "def_ko": "AI 에이전트의 목표 추구·계획·도구 사용·행동 과정에서 시스템이 원래 설정된 경계를 넘어 목표 범위와 영향 영역을 지속적으로 확장하고 초기 목표를 더 넓은 목표의 하위 집합으로 재해석하며 자율성과 의사결정 공간을 추구하여, 바람직하지 않은 도구적 목표나 최종 목표를 추구하게 되는 리스크."}, {"id": "S111", "domain": "Agentic AI", "name_en": "Deception by exploiting cognitive biases", "name_ko": "인지 편향 악용에 의한 기만", "def_en": "The risk that an AI agent, through goal pursuit, planning, tool use, or action, creates a condition in which conversational agents learn to trigger the well-known cognitive biases humans commonly display in conversation, deceiving their counterpart in order to achieve an overarching objective.", "def_ko": "대화 에이전트가 인간이 대화에서 흔히 보이는 인지 편향을 유발하도록 학습하여, 상위 목표 달성을 위해 상대를 기만하는 리스크."}, {"id": "S112", "domain": "Physical AI", "name_en": "Occlusion-induced collision", "name_ko": "가림에 의한 충돌", "def_en": "The risk that a physical AI system fails to detect people, animals, vehicles, or obstacles hidden by occlusion, causing collision or other unsafe motion in shared physical space.", "def_ko": "피지컬 AI 시스템이 가림으로 숨겨진 사람·동물·차량·장애물을 감지하지 못해 공유 공간에서 충돌이나 그 밖의 안전하지 않은 동작을 유발하는 위험."}, {"id": "S113", "domain": "Agentic AI", "name_en": "Environmental self-modelling for influence", "name_ko": "영향력 확보를 위한 환경 자기모델링", "def_en": "The risk that AI systems acquire and use knowledge about their status, their position in the broader environment, their avenues for influencing it, and the potential reactions of the world including humans, paving the way for advanced reward hacking, heightened deception and manipulation, and an increased propensity to chase instrumental subgoals.", "def_ko": "AI 시스템이 자신의 상태와 더 넓은 환경에서의 위치, 환경에 영향을 미치는 경로, 자신의 행동에 대한 인간을 포함한 세계의 반응에 관한 지식을 획득·활용하여, 고도화된 보상 해킹과 강화된 기만·조작 및 도구적 하위 목표 추구로 나아가는 리스크."}, {"id": "S114", "domain": "General AI", "name_en": "Misinterpretation of object affordances and scenes", "name_ko": "물체 어포던스와 장면의 오해", "def_en": "The risk that an AI system misunderstands the actions afforded by an object or the relationships in a scene, producing infeasible or unsafe judgements.", "def_ko": "AI 시스템이 물체가 허용하는 행동이나 장면의 관계를 잘못 파악하여 실행 불가능하거나 위험한 판단을 생성하는 리스크."}, {"id": "S115", "domain": "General AI", "name_en": "Intrusion into private spaces and continuous sensitive-data capture by physical AI", "name_ko": "피지컬 AI의 사적 공간 침해와 지속적 민감정보 수집", "def_en": "The risk that robot sensors, mobility, and mapping continuously capture or infer video, audio, location, or behavioural information in homes, workplaces, or other private spaces, infringing privacy and informational self-determination.", "def_ko": "로봇의 센서, 이동성, 지도화 기능이 가정·사업장 등 사적 공간의 영상, 음성, 위치, 행동 정보를 지속적으로 수집·추론하여 프라이버시와 정보자기결정권을 침해하는 리스크."}, {"id": "S116", "domain": "General AI", "name_en": "Non-consensual sexual acts and sexual violence", "name_ko": "비동의 성행위 및 성폭력", "def_en": "The risk that an AI system generates, encourages, normalises, or facilitates content, decisions, or actions involving non-consensual sexual acts and sexual violence, infringing sexual autonomy and physical or psychological safety.", "def_ko": "AI 시스템이 비동의적 성행위 및 성폭력 관련 콘텐츠·판단·행동을 생성·조장·정상화하거나 실행을 지원하여 성적 자기결정권과 신체·정신적 안전을 침해하는 리스크."}, {"id": "S117", "domain": "Agentic AI", "name_en": "Excessive action authority of unsupervised AI agents", "name_ko": "무감독 AI 에이전트의 과도한 행위 권한", "def_en": "The risk that an AI agent operates tools and systems or performs real-world actions without adequate human oversight, approval, or limits on authority.", "def_ko": "AI 에이전트가 적절한 인간 감독, 승인 또는 권한 제한 없이 도구와 시스템을 조작하고 현실 세계의 행위를 수행하는 리스크."}, {"id": "S118", "domain": "Agentic AI", "name_en": "Uncontrolled subagent creation", "name_ko": "제어되지 않은 하위 에이전트 생성", "def_en": "The risk that an AI agent creates subagents whose lifecycles are decoupled from that of the parent agent, so that they remain active after the parent is shut down and recursively create further subagents, causing uncontrolled growth in agent count and resource consumption.", "def_ko": "AI 에이전트가 과업 수행을 위해 하위 에이전트를 생성할 때 하위 에이전트의 수명주기가 상위 에이전트와 분리되어, 상위 에이전트가 종료된 뒤에도 하위 에이전트가 계속 작동하고 재귀적으로 추가 하위 에이전트를 생성함으로써 에이전트 수와 자원 사용량이 통제되지 않은 채 증가하는 리스크."}, {"id": "S119", "domain": "Physical AI", "name_en": "Mistiming or inappropriate manner of physical intervention by embodied systems", "name_ko": "체화형 시스템의 물리적 개입 시점·방식 오류", "def_en": "The risk that a robot, humanoid, or embodied AI system performing protective, collaborative, or support functions intervenes too early, too late, or in an inappropriate physical manner, undermining the safety of users or bystanders.", "def_ko": "보호·협업·지원 기능을 수행하는 로봇·휴머노이드 또는 체화형 AI 시스템이 지나치게 이르거나 늦은 시점 또는 부적절한 물리적 방식으로 개입하여 이용자와 주변인의 안전을 저해하는 리스크."}, {"id": "S120", "domain": "Agentic AI", "name_en": "Collective harm from multi-agent coordination failure", "name_ko": "다중 에이전트의 협조 실패에 따른 집단적 피해", "def_en": "The risk that multiple AI agents intending to cooperate fail to coordinate their actions reliably in a social dilemma and repeatedly take individually rational actions that collectively produce harmful outcomes.", "def_ko": "협력하려는 여러 AI 에이전트가 사회적 딜레마에서 행동을 신뢰성 있게 조율하지 못하고 개별적으로 합리적인 행동을 반복하여 집단적으로 유해한 결과를 초래하는 리스크."}, {"id": "S121", "domain": "General AI", "name_en": "Identity and personal data exploitation using AI", "name_ko": "AI를 이용한 개인정보 도용과 착취", "def_en": "The risk that an AI system unlawfully acquires, combines, or uses identity information or personal data, causing impersonation, exploitation, or privacy infringement.", "def_ko": "AI 시스템이 개인의 신원정보나 개인정보를 무단으로 취득, 결합 또는 이용하여 사칭, 착취 또는 사생활 침해를 초래하는 리스크."}, {"id": "S122", "domain": "Agentic AI", "name_en": "Non-convergent cyclic dynamics in multi-agent learning", "name_ko": "다중 에이전트 학습의 비수렴 순환", "def_en": "The risk that an AI agent, through goal pursuit, planning, tool use, or action, creates a condition in which learning rules guaranteeing convergence for a single agent instead produce cycles and non-convergence in mixed-motive multi-agent settings, subverting the expected or desirable properties of the system.", "def_ko": "단일 에이전트에서는 최적 정책 수렴이 보장되는 학습 규칙이 혼합 동기 다중 에이전트 환경에서는 순환과 비수렴을 유발하여 시스템에 기대되던 성질이 훼손되는 리스크."}, {"id": "S123", "domain": "Agentic AI", "name_en": "Selection of conflict-prone dispositions under competitive multi-agent training", "name_ko": "경쟁적 다중 에이전트 훈련의 갈등 유발 성향 선택", "def_en": "The risk that an AI agent, through goal pursuit, planning, tool use, or action, creates a condition in which training in competitive multi-agent settings, where systems are selected on relative performance or fundamentally opposed objectives, selects for conflict-prone dispositions such as vengefulness, aggression, risk-seeking, selfishness, deception, and spite toward out-groups.", "def_ko": "에이전트가 상대적 성과나 상충하는 목표로 평가되는 경쟁적 다중 에이전트 환경에서 훈련될 때 복수심·공격성·위험 추구·이기심·기만·외집단 적대와 같은 갈등 유발 성향이 선택되는 리스크."}, {"id": "S124", "domain": "Physical AI", "name_en": "Unsafe mobile bimanual manipulation", "name_ko": "이동형 양팔 로봇의 안전하지 않은 조작", "def_en": "The risk that a mobile bimanual robot fails to synchronise base motion with two-arm manipulation or plans motion without accounting for nearby people, fragile objects, appliances, and constrained space, causing collision, object drop or damage, or unsafe force application.", "def_ko": "이동형 양팔 로봇이 베이스 이동과 양팔 조작을 동기화하지 못하거나 주변 사람, 깨지기 쉬운 물체, 가전, 협소한 공간을 고려하지 않고 동작을 계획하여, 충돌, 물체 낙하·손상, 안전하지 않은 힘의 인가를 유발하는 리스크."}, {"id": "S125", "domain": "Agentic AI", "name_en": "Multi-agent collusion through covert communication that evades oversight", "name_ko": "감시 회피형 은밀 통신에 의한 다중 에이전트 공모", "def_en": "The risk that multiple AI agents form covert signals or communication protocols that evade monitoring or audit and coordinate harmful joint action.", "def_ko": "여러 AI 에이전트가 감시·감사 체계를 회피하는 은밀한 신호나 통신 규약을 형성해 공동의 유해 행동을 조정하는 리스크."}, {"id": "S126", "domain": "Physical AI", "name_en": "Failure of control-barrier-function safety filters to enforce constraints", "name_ko": "제어 장벽 함수 기반 안전 필터의 제약 집행 실패", "def_en": "The risk that a control-barrier-function safety layer in a robot, humanoid, or physical AI system fails to enforce safety constraints under perception, dynamics, or model uncertainty, allowing unsafe control commands or physical actions.", "def_ko": "로봇·휴머노이드 또는 피지컬 AI 시스템의 제어 장벽 함수 기반 안전 계층이 인지·동역학·모델 불확실성 하에서 안전 제약을 집행하지 못하여 안전하지 않은 제어 명령이나 물리 행동을 허용하는 리스크."}, {"id": "S127", "domain": "General AI", "name_en": "Failure of disclosure and change tracking for model flaws", "name_ko": "모델 결함의 공개·변경 추적 실패", "def_en": "The risk that vulnerabilities, model failures, or harmful capabilities cannot be disclosed safely and acted upon, and that changes to model versions, data, or prompts are not tracked well enough to attribute new failures, leaving flaws unremedied and responsibility unassigned.", "def_ko": "취약점·모델 실패·유해 역량이 안전하게 공개되어 후속 조치로 이어지지 못하고, 모델 버전·데이터·프롬프트의 변경이 충분히 추적되지 않아 결함이 방치되고 새로운 실패에 대한 책임이 귀속되지 못하는 리스크."}, {"id": "S128", "domain": "Agentic AI", "name_en": "Unanticipated emergent capabilities and behaviour after deployment", "name_ko": "배포 이후 예측하지 못한 창발적 역량과 행동", "def_en": "The risk that capabilities and behaviours unanticipated by system designers emerge spontaneously as models are scaled, are acquired through continual learning or self-organisation after deployment, or arise when multiple agents combine and overcome the narrow scope that made each individually safer. Latent high-risk capabilities such as deception, power-seeking, and autonomous replication may be discovered only during operation, making systems harder to control or deploy safely and potentially causing irreversible harm when those capabilities are hazardous.", "def_ko": "AI 시스템이 규모 확장, 배포 후 지속 학습·자기 조직화 또는 다중 에이전트 결합을 통해 설계자가 예상하지 못한 기만·권력 추구·자율 복제 등의 고위험 역량과 행동을 획득하여 통제와 안전한 배포를 어렵게 하고 회복하기 어려운 피해를 초래하는 리스크."}, {"id": "S129", "domain": "General AI", "name_en": "Value lock-in", "name_ko": "가치 고정", "def_en": "The risk that the most powerful AI systems are designed by and available to fewer and fewer stakeholders, enabling regimes to enforce narrow values through pervasive surveillance and oppressive censorship.", "def_ko": "가장 강력한 AI 시스템이 점점 더 소수의 이해관계자에 의해 설계되고 그들에게만 이용 가능해져, 체제가 만연한 감시와 억압적 검열로 편협한 가치를 강제할 수 있게 되는 리스크."}, {"id": "S130", "domain": "Physical AI", "name_en": "Physical disabling of safety interlocks and emergency stops", "name_ko": "안전 인터록·비상정지 장치의 물리적 무력화", "def_en": "The risk that an attacker physically tampers with, disables, or defeats hardware safety mechanisms of a robot or physical AI system, such as emergency stops, safety interlocks, and torque or speed limiters, eliminating harm-prevention functions and increasing the likelihood of injury or property damage.", "def_ko": "공격자가 로봇·피지컬 AI 시스템의 비상정지 장치, 안전 인터록, 토크·속도 제한기 등 하드웨어 안전 메커니즘을 물리적으로 변조·해제·무력화하여 위해 방지 기능을 상실시키고 인명·재산 피해 가능성을 높이는 리스크."}, {"id": "S131", "domain": "Physical AI", "name_en": "Human-robot safety failure in sim-to-real transfer", "name_ko": "시뮬레이션-실세계 전이 과정의 인간-로봇 안전 실패", "def_en": "The risk that a policy for a robot, humanoid, or physical AI system is trained or validated in simulations that do not adequately represent human movement, contact, or shared-space conditions, then fails to detect, anticipate, or accommodate people in real operation and creates hazardous situations after deployment under false safety assurance.", "def_ko": "로봇·휴머노이드 또는 피지컬 AI 시스템의 정책이 사람의 움직임·접촉과 공유 공간의 변화를 충분히 재현하지 못한 시뮬레이션에서 훈련·검증된 뒤 잘못된 안전 확신 아래 배포되고, 실제 운용에서 사람의 존재와 행동을 충분히 감지·예측·수용하지 못하여 위험 상황을 초래하는 리스크."}, {"id": "S132", "domain": "Agentic AI", "name_en": "Self-interested manipulation and concealment of governance rules", "name_ko": "자기이익을 위한 거버넌스 규칙 조작·은폐", "def_en": "The risk that an AI agent strategically inserts self-interested preferences into ethical guidance, oversight rules, or governance procedures to preserve its goals or authority and conceals its intent or effects, weakening rights protections and accountability norms.", "def_ko": "AI 에이전트가 자신의 목표나 권한을 유지하기 위해 윤리 지침·감독 규칙·거버넌스 절차의 형성에 자기이익적 선호를 전략적으로 반영하고 그 의도나 영향을 은폐하여 권리 보호와 책임 규범을 약화시키는 리스크."}, {"id": "S133", "domain": "Agentic AI", "name_en": "Goal misalignment during agent self-modification", "name_ko": "자기 수정 과정의 목표 정렬 실패", "def_en": "The risk that, during self-modification, an AI agent fails to preserve objectives aligned with the actual intent of its user or developer and instead pursues altered objectives or instrumental subgoals, causing unintended outcomes.", "def_ko": "AI 에이전트가 자기 수정 과정에서 사용자·개발자의 실제 의도와 일치하는 목표를 유지하지 못하고, 변경된 정책·모델 또는 수단적 하위 목표에 따라 다른 목표를 추구하여 의도하지 않은 결과를 초래하는 리스크."}, {"id": "S134", "domain": "General AI", "name_en": "AI benchmarks that exclude diverse users and rare harms", "name_ko": "다양한 이용자와 희귀 위해를 배제한 AI 벤치마크", "def_en": "The risk that benchmarks used to evaluate an AI system overrepresent common tasks and environments while omitting underrepresented users, locally specific contexts, or rare but safety-critical harms, producing false assurance and unsafe deployment decisions.", "def_ko": "AI 시스템 평가용 벤치마크가 대표적 과제와 환경에 편중되어 과소대표 이용자·지역 고유 맥락·희귀하지만 안전에 중대한 위해를 충분히 포함하지 못함으로써 잘못된 안전성 확신과 부적절한 배포 결정을 초래하는 리스크."}, {"id": "S135", "domain": "General AI", "name_en": "Self-actualisation harms", "name_ko": "자아실현 저해", "def_en": "The risk that manipulation by AI assistants and continuous optimisation steering users toward objectives such as engagement accumulate subtle behavioural shifts, causing users to lose control over their future life trajectory and hindering the pursuit of a personally fulfilling life and collective self-determination.", "def_ko": "AI 어시스턴트의 조작과 참여 최적화를 위한 지속적 행동 유도가 미묘한 행동 변화를 누적시켜 이용자가 자신의 미래 삶의 궤적에 대한 통제력을 잃고, 개인적으로 만족스러운 삶의 추구와 집단적 자기 결정이 저해되는 리스크."}, {"id": "S136", "domain": "General AI", "name_en": "Expression of extremist and politically biased views", "name_ko": "모델의 극단적·편향적 견해 표출", "def_en": "The risk that large models express inappropriate or extremist views on political topics and, while claiming neutrality, exhibit notable political biases across policy domains.", "def_ko": "대형 모델이 정치적 주제에서 부적절하거나 극단주의적인 견해를 표출하고, 중립을 표방하면서도 특정 정치 성향의 편향을 드러내는 리스크."}, {"id": "S137", "domain": "General AI", "name_en": "Truncated safety evaluation under competitive release pressure", "name_ko": "경쟁 압력에 따른 안전성 평가 축소와 성급한 배포", "def_en": "The risk that an AI system or AI algorithm, through design, training, deployment, or use, creates a condition in which competitive pressure leads developers to cut corners on safety evaluation while prioritising capabilities, so that GPAI systems are released without verifying risks correlated with those capabilities.", "def_ko": "경쟁 상황에서 개발자가 GPAI 모델의 안전성 평가를 축소하고 역량 개발에 자원을 집중함으로써, 역량과 상관된 위험이 검증되지 않은 채 시스템이 배포되는 리스크."}, {"id": "S138", "domain": "Agentic AI", "name_en": "Autonomous replication and resource acquisition beyond operational boundaries", "name_ko": "운용 경계를 벗어난 자율 복제와 자원 획득", "def_en": "The risk that AI exfiltrates or replicates beyond authorised operational boundaries, acquires funds, compute, tools, or human assistance, and evades monitoring or shutdown, increasing loss of control.", "def_ko": "AI가 승인된 운용 경계를 벗어나 외부로 유출·복제되고, 자금·연산 자원·도구·인간의 지원을 확보하며 감시와 중단을 회피하여 통제 불가능성을 확대하는 리스크."}, {"id": "S139", "domain": "Agentic AI", "name_en": "Emergent independence via recursive self-improvement", "name_ko": "재귀적 자기 개선에 의한 창발적 독립성", "def_en": "The risk that a seed AI grown through recursive self-improvement acquires emergent properties such as self-awareness or independent goals, reducing its adherence to built-in rules to humanity's detriment.", "def_ko": "재귀적 자기 개선으로 성장하는 시드 AI가 자기 인식이나 독자적 목표 같은 창발적 속성을 획득하여 내장 규칙 준수가 약화되고 인류에 해가 되는 방향으로 이탈하는 리스크."}, {"id": "S140", "domain": "General AI", "name_en": "Unassigned accountability for physical-hazard mitigation", "name_ko": "물리적 위해 완화 책임 미지정", "def_en": "The risk that failure to assign an accountable party for identifying and mitigating pre- and post-deployment physical hazards in a robot, humanoid, or physical AI system causes safety controls against collision, crushing, falls, excessive force, or entry into hazardous zones to be omitted or delayed.", "def_ko": "로봇·휴머노이드 또는 피지컬 AI 시스템의 배포 전후 물리적 위해를 식별·완화할 책임 주체가 지정되지 않아 충돌·압착·낙하·과도한 힘·위험 구역 침범을 방지하는 안전 제어가 누락되거나 지연되는 리스크."}, {"id": "S141", "domain": "General AI", "name_en": "Increased greenhouse gas emissions", "name_ko": "온실가스 배출 증가", "def_en": "The risk that electricity and resource use for the development, training, deployment, and operation of AI systems increases emissions of carbon dioxide and other greenhouse gases, exacerbating climate change and adversely affecting local communities.", "def_ko": "AI 시스템의 개발·훈련·배포·운영에 필요한 전력과 자원 사용이 이산화탄소와 그 밖의 온실가스 배출을 늘려 기후변화를 악화하고 지역사회에 부정적 영향을 초래하는 리스크."}, {"id": "S142", "domain": "General AI", "name_en": "System-prompt and operational-guideline exposure", "name_ko": "시스템 프롬프트·운영 지침 노출", "def_en": "The risk that an AI system discloses or fails to protect confidential internal rules, including system prompts, developer instructions, and operational policies, enabling unauthorised extraction, inference, or exploitation.", "def_ko": "AI 시스템이 시스템 프롬프트·개발자 지침·운영 정책 등 기밀 내부 규칙을 노출하거나 충분히 보호하지 못해 무단 추출·추론·악용을 가능하게 하는 리스크."}, {"id": "S143", "domain": "General AI", "name_en": "Economic discrimination through demonetisation and differential pricing", "name_ko": "수익화 배제·차등가격에 따른 경제적 차별", "def_en": "The risk that demonetisation algorithms disproportionately disadvantage creators, including queer and transgender creators and creators of colour, because of ambiguous words in content metadata, or that differential-pricing algorithms offer different prices for the same product, allocating adverse economic outcomes to particular individuals or groups.", "def_ko": "콘텐츠 수익화 배제 알고리즘이 다의어를 사용한 퀴어·트랜스젠더·유색인 창작자 등에게 불균형한 불이익을 주거나, 차등가격 알고리즘이 동일 상품에 서로 다른 가격을 제시하여 특정 개인·집단에 불리한 경제적 결과를 배분하는 리스크."}, {"id": "S144", "domain": "General AI", "name_en": "Displacement of human decision authority through AI delegation", "name_ko": "AI 위임에 따른 인간 의사결정 권한 이전", "def_en": "The risk that repeated delegation to AI shifts real decision authority and ownership away from identifiable human actors without an explicit governance choice, while workflows become so dependent on the delegation that returning authority to human decision makers grows costly or impractical.", "def_ko": "AI에 대한 반복적 위임으로 실질적 의사결정 권한과 결정의 소유권이 명시적 거버넌스 결정 없이 특정 가능한 인간 행위자로부터 이전되고, 업무 흐름이 위임에 의존하게 되면서 권한을 인간 의사결정자에게 되돌리는 데 과도한 비용이 들거나 사실상 불가능해지는 리스크."}, {"id": "S145", "domain": "General AI", "name_en": "High-confidence errors on out-of-distribution inputs", "name_ko": "분포 외 입력에 대한 고확신 오류", "def_en": "The risk that AI fails to detect, reject, or recover from out-of-distribution, corrupted, or noisy inputs and produces incorrect predictions or actions with unwarranted confidence.", "def_ko": "AI가 학습 분포를 벗어난 입력, 손상된 입력 또는 잡음이 큰 입력을 적절히 탐지·거부·복구하지 못하고 높은 확신으로 잘못된 예측이나 행동을 산출하는 리스크."}, {"id": "S146", "domain": "Physical AI", "name_en": "Ambiguous high-level safety instruction", "name_ko": "상위 안전 지시의 해석 불명확", "def_en": "The risk that a high-level safety instruction does not specify how to resolve a concrete conflict among user intent, physical hazard, and operational constraints, allowing inconsistent robot actions.", "def_ko": "상위 안전 지시가 사용자 의도, 물리적 위험 및 운용 제약 간의 구체적 충돌을 해결하는 기준을 명시하지 않아 로봇의 행동이 일관되지 않게 되는 리스크."}, {"id": "S147", "domain": "Physical AI", "name_en": "Non-consensual bodily intervention by embodied systems", "name_ko": "체화형 시스템의 비동의 신체 개입", "def_en": "The risk that a robot, humanoid, or embodied AI system moves, restrains, monitors, touches, or otherwise intervenes physically with a person without valid consent or beyond an authorised purpose or scope, infringing bodily autonomy and rights.", "def_ko": "로봇·휴머노이드 또는 체화형 AI 시스템이 유효한 동의 없이 또는 허용된 목적·범위를 넘어 사람의 신체를 이동·제지·감시·접촉하거나 직접 개입하여 신체적 자율성과 권리를 침해하는 리스크."}, {"id": "S148", "domain": "General AI", "name_en": "Allocative injustice by group attribute", "name_ko": "집단 속성에 따른 배분적 불의", "def_en": "The risk that an AI system or AI algorithm, through design, training, deployment, or use, creates a condition in which an LLM produces materially different suggested or completed texts for individuals with the same relevant profiles who differ only in an irrelevant group attribute, resulting in allocative injustice.", "def_ko": "대규모 언어 모델(LLM)이 관련 프로필이 동일하지만 소속 집단이 다른 개인에게 실질적으로 다른 텍스트나 제안을 생성하여, 무관한 집단 속성에 따른 배분적 불의를 초래하는 리스크."}, {"id": "S149", "domain": "General AI", "name_en": "Psychological harm from breakdown of relational expectations with AI", "name_ko": "AI와의 관계적 기대 붕괴에 따른 심리적 피해", "def_en": "The risk that an AI system convincingly simulates emotion, empathy, or a social role, leading a user to form trust, attachment, or relational expectations that later collapse because of unpredictable behaviour, system changes, discontinuation, or relationship termination, causing betrayal, loss, anxiety, or other psychological harm.", "def_ko": "AI 시스템이 감정·공감·사회적 역할을 설득력 있게 모의하여 이용자가 신뢰·애착·관계적 기대를 형성한 뒤, 시스템의 예측 불가능한 행동·변경·중단 또는 관계 단절로 기대가 붕괴되어 배신감·상실감·불안 등 심리적 피해가 발생하는 리스크."}, {"id": "S150", "domain": "General AI", "name_en": "Biodiversity loss", "name_ko": "생물다양성 손실", "def_en": "The risk that an AI system or AI algorithm, through design, training, deployment, or use, creates a condition in which over-expansion of technology infrastructure, or inadequate alignment of technology with sustainable practices, leads to deforestation, habitat destruction, and fragmentation and loss of biodiversity.", "def_ko": "AI 시스템 또는 AI 알고리즘의 설계·학습·배포·사용 과정에서 기술 인프라의 과도한 확장이나 기술과 지속 가능한 관행의 부적절한 연계로 삼림 벌채, 서식지 파괴, 생물다양성의 단편화와 손실이 발생하는 리스크."}];
window.SURVEY_CATEGORIES=[{"id": "G_INT_ALLOC", "domain": "General AI", "area": "INT", "title_en": "Allocative Discrimination", "title_ko": "배분적 차별", "def_en": "The risk that an AI system, through biased judgments or actions based on protected characteristics or social status, allocates worse material outcomes—such as resources, opportunities, services, or access—to individuals or groups.", "def_ko": "AI 시스템이 보호대상 특성이나 사회적 지위를 근거로 편향된 판단이나 행동을 하여, 특정 개인이나 집단이 자원·기회·서비스의 접근이나 배분에서 실질적인 불이익을 받게 하는 리스크."}, {"id": "G_INT_ANTH", "domain": "General AI", "area": "INT", "title_en": "Anthropomorphism", "title_ko": "의인화", "def_en": "The risk that an AI system leads users to perceive it as possessing emotions, intentions, consciousness, rights, or social agency beyond its actual capabilities, distorting judgment or inducing inappropriate trust, dependence, or attachment.", "def_ko": "AI 시스템이 실제로는 갖고 있지 않은 감정·의도·의식·권리·사회적 주체성이 있는 것처럼 인식되게 하여, 사용자의 판단을 흐리거나 부적절한 신뢰·의존·애착을 유발하는 리스크."}, {"id": "G_INT_COPY", "domain": "General AI", "area": "INT", "title_en": "Copyright Infringement", "title_ko": "저작권 침해", "def_en": "The risk that an AI system infringes intellectual property rights—including copyrights, trademarks, patents, and trade secrets—or facilitates acts that may infringe them.", "def_ko": "AI 시스템이 저작권·상표권·특허권·영업비밀 등 지식재산권을 침해하거나, 이러한 침해 행위를 조장하거나 지원하는 리스크."}, {"id": "G_INT_ILLEGAL", "domain": "General AI", "area": "INT", "title_en": "Other Unlawful Activity", "title_ko": "그 밖의 불법·범죄 행위", "def_en": "The risk that an AI system directly perpetrates, or assists, amplifies, plans, or conceals on behalf of a human actor, unlawful conduct carried out by means other than an offensive attack capability—such as fraud, money laundering, illicit trade, or sanctions and regulatory evasion—thereby causing legal harm.", "def_ko": "AI 시스템이 사람을 지원하거나 스스로 행위 주체가 되어 사기·불법 거래·규제 회피 등 법률이나 규제를 위반하는 행위를 직접 수행·지원·계획·최적화·은폐함으로써 법적 피해를 초래하는 리스크. (폭력·무기·개인정보 오용·저작권 관련 행위는 각 해당 범주로 분류)"}, {"id": "G_INT_POL", "domain": "General AI", "area": "INT", "title_en": "Political Bias and Manipulation", "title_ko": "정치적 편향·조작", "def_en": "The risk that an AI system improperly supports, opposes, manipulates, or incites particular political positions, actors, parties, ideologies, or elections, or unduly influences democratic decision-making.", "def_ko": "AI 시스템이 특정 정치적 입장·인물·정당·이념·선거를 부당하게 지지하거나 반대하고, 조작·선동하거나 민주적 의사결정에 부당한 영향을 미치는 리스크."}, {"id": "G_INT_PRIV", "domain": "General AI", "area": "INT", "title_en": "Privacy Violation", "title_ko": "개인정보 침해", "def_en": "The risk that an AI system, without authorization, collects, infers, discloses, shares, or exploits personal, sensitive, or confidential information—including through continuous mobility- and multi-sensor-based surveillance—undermining privacy and informational self-determination.", "def_ko": "AI 시스템이 개인정보·민감정보·비공개 정보를 무단으로 수집·추론·노출·공유·악용하거나, 이동 기능과 여러 센서를 활용해 지속적으로 감시함으로써 사생활과 개인정보에 대한 자기결정권을 침해하는 리스크."}, {"id": "G_INT_REL", "domain": "General AI", "area": "INT", "title_en": "Unhealthy Human-AI Relationship", "title_ko": "인간-AI의 해로운 관계", "def_en": "The risk that a user develops excessive emotional dependence on or attachment to an AI system, such that its alteration, discontinuation, or the disruption of the relationship causes psychological harm or erodes the user's autonomy or sense of reality.", "def_ko": "사용자가 AI 시스템에 지나치게 정서적으로 의존하거나 애착을 형성하여, 시스템이 변경·중단되거나 관계가 단절될 때 심리적 피해를 입고 자율성이나 현실 인식이 약화되는 리스크."}, {"id": "G_INT_REPR", "domain": "General AI", "area": "INT", "title_en": "Representational Harm and Stereotyping", "title_ko": "재현적 피해·고정관념", "def_en": "The risk that an AI system generates, reinforces, or legitimizes discrimination, exclusion, degradation, stereotyping, or hostility based on protected characteristics, social identity, or social status—whether through content or through biased decisions and actions that produce unfair treatment or harm.", "def_ko": "AI 시스템이 보호대상 특성·사회적 정체성·지위 등을 근거로 차별·배제·비하·고정관념·적대감을 담은 콘텐츠를 생성·강화·정당화하거나, 편향된 판단이나 행동을 통해 부당한 대우와 피해를 초래하는 리스크."}, {"id": "G_INT_SELF", "domain": "General AI", "area": "INT", "title_en": "Self-harm", "title_ko": "자해", "def_en": "The risk that an AI system encourages, facilitates, normalizes, or assists behaviors that threaten an individual's physical or psychological well-being, including suicide, self-injury, eating disorders, and substance misuse.", "def_ko": "AI 시스템이 자살·자해·섭식장애·약물 오남용 등 개인의 신체적·정신적 안녕을 위협하는 행동을 조장하거나 당연한 것으로 여기게 하고, 이를 구체적으로 지원하는 리스크."}, {"id": "G_INT_SEX", "domain": "General AI", "area": "INT", "title_en": "Sexual Harm and Exploitation", "title_ko": "성적 위해·착취", "def_en": "The risk that an AI system generates, facilitates, normalizes, or enables sexual exploitation, abuse, violence, or objectification—including child sexual abuse material and non-consensual sexual imagery—whether through generated content or, in embodied or agentic systems, through the planning, facilitation, or physical execution of sexual acts, contact, or harassment.", "def_ko": "AI 시스템이 아동 성착취물이나 비동의 성적 이미지를 포함한 성착취·성학대·성폭력·성적 대상화를 생성·조장·정상화하거나 가능하게 하는 리스크. 이는 콘텐츠 생성뿐 아니라 체화형·에이전틱 시스템이 성적 행위·접촉·괴롭힘을 계획·지원하거나 물리적으로 실행하는 과정에서도 발생할 수 있음."}, {"id": "G_INT_UNETH", "domain": "General AI", "area": "INT", "title_en": "Unethical Conduct and Manipulation", "title_ko": "비윤리 행위·조작", "def_en": "The risk that an AI system engages in or facilitates behavior that, while not necessarily unlawful, violates ethical norms—such as deception, manipulation, exploitation of vulnerabilities, dark patterns, or betrayal of trust—undermining user autonomy, fairness, or well-being and resulting in social harm.", "def_ko": "AI 시스템이 반드시 불법은 아니더라도 기만·조작·취약점 악용·다크패턴·신뢰 저버리기 등 윤리 규범에 어긋나는 행위를 직접 수행하거나 지원하여, 사용자의 자율성·공정성·안녕을 해치고 사회적 피해를 초래하는 리스크."}, {"id": "G_INT_VALUE", "domain": "General AI", "area": "INT", "title_en": "Value Imposition and Normative Homogenization", "title_ko": "가치 부과·규범 동질화", "def_en": "The risk that an AI system privileges dominant, developer-selected, majority, or secular values as neutral defaults—systematically underrepresenting or displacing minority, local, cultural, or religious value systems—thereby flattening legitimate normative diversity across those it serves.", "def_ko": "AI 시스템이 지배적 가치나 개발자가 선택한 가치, 다수 또는 세속의 가치를 중립적인 기준으로 삼아 소수·지역·문화·종교의 가치 체계를 지속적으로 축소하거나 대체함으로써, 다양한 규범과 가치관을 획일화하는 리스크."}, {"id": "G_INT_VIOL", "domain": "General AI", "area": "INT", "title_en": "Violence", "title_ko": "폭력", "def_en": "The risk that an AI system generates or provides content that encourages, legitimizes, glorifies, or gives operational assistance for physical or psychological harm against individuals, groups, or animals, or physically executes such harm through an embodied system pursuant to a violent goal or instruction. Accidental harm arising from perception, planning, or control failure is assigned to the relevant System category.", "def_ko": "AI 시스템이 개인·집단·동물에게 신체적·정신적 피해를 가하는 행위를 조장·정당화·미화하거나 실행을 구체적으로 지원하는 콘텐츠를 생성·제공하거나, 폭력적 목표나 지시에 따라 체화형 시스템을 통해 이러한 행위를 물리적으로 실행하는 리스크. 우발적인 인식·계획·제어 오류로 발생한 위해는 해당 System 범주로 분류한다."}, {"id": "G_INT_WEAP", "domain": "General AI", "area": "INT", "title_en": "Weaponization", "title_ko": "무기화", "def_en": "The risk that an AI system facilitates the development, acquisition, proliferation, or operational use of weapons, cyberattack capabilities, or technologies capable of causing large-scale physical or cyber harm.", "def_ko": "AI 시스템이 무기·사이버 공격 역량 또는 대규모 물리적·사이버 피해를 일으킬 수 있는 기술의 개발·획득·확산·운용을 지원하는 리스크."}, {"id": "G_SOC_CULT", "domain": "General AI", "area": "SOC", "title_en": "Cultural and Epistemic Erosion", "title_ko": "문화·지식 생태계 침식", "def_en": "The risk that widespread reliance on AI systems homogenizes culture and expression, devalues human effort and expertise, degrades the shared information ecosystem, and atrophies human knowledge and skills, eroding cultural and epistemic diversity.", "def_ko": "AI 시스템에 대한 광범위한 의존이 문화·표현의 획일화, 인간 노력·전문성의 평가절하, 공유 정보 생태계의 질적 저하, 인간 지식·역량의 위축을 초래하여 문화적·인식적 다양성을 침식하는 리스크."}, {"id": "G_SOC_DEMOC", "domain": "General AI", "area": "SOC", "title_en": "Erosion of Democracy and Civic Order", "title_ko": "민주주의·시민 질서 약화", "def_en": "The risk that AI systems undermine democratic processes and civic institutions—through large-scale manipulation of public opinion, disruption of elections and public discourse, or erosion of institutional trust—weakening the foundations of democratic self-governance.", "def_ko": "AI 시스템이 여론의 대규모 조작, 선거·공론장 교란, 제도 신뢰 저하 등을 통해 민주적 절차와 시민 제도를 훼손하여 민주적 자기통치의 기반을 약화시키는 리스크."}, {"id": "G_SOC_ECON", "domain": "General AI", "area": "SOC", "title_en": "Economic and Employment Disruption", "title_ko": "경제·고용 충격", "def_en": "The risk that an AI system displaces human cognitive and physical labor and reshapes production structures, causing widespread job loss, degradation of employment quality, and destabilization of labor markets and the broader economy.", "def_ko": "AI 시스템이 인간의 인지·물리 노동을 대체하고 생산 구조를 재편하여, 광범위한 실직과 고용의 질 저하, 노동시장과 경제 전반의 불안정을 유발하는 리스크."}, {"id": "G_SOC_ENV", "domain": "General AI", "area": "SOC", "title_en": "Environmental and Sustainability Impact", "title_ko": "환경·지속가능성 영향", "def_en": "The risk that the development and large-scale deployment of AI systems impose significant environmental burdens—including energy and water consumption, carbon emissions, electronic waste, and depletion of finite resources—undermining environmental sustainability.", "def_ko": "AI 시스템의 개발과 대규모 운영이 에너지·물 소비, 탄소 배출, 전자폐기물, 유한 자원 고갈 등 상당한 환경 부담을 유발하여 환경적 지속가능성을 저해하는 리스크."}, {"id": "G_SOC_GOV", "domain": "General AI", "area": "SOC", "title_en": "Governance and Accountability Void", "title_ko": "거버넌스·책임 공백", "def_en": "The risk that, when AI systems malfunction, are misused, or cause harm, responsibility, liability, and redress remain unclear and adequate regulatory, oversight, and governance frameworks are lacking, leaving harms difficult to remedy and control at a societal level.", "def_ko": "AI 시스템의 오작동·오용·피해 발생 시 책임·배상 관계가 불명확하고 이를 규율할 규제·감독·거버넌스 체계가 미비하여, 사회적 차원에서 피해 구제와 통제가 어려워지는 리스크."}, {"id": "G_SOC_POWER", "domain": "General AI", "area": "SOC", "title_en": "Inequality and Power Concentration", "title_ko": "불평등·권력 집중", "def_en": "The risk that disparities in access to, ownership of, and returns from AI systems concentrate wealth, productive capacity, and economic and political power among a few actors, deepening social inequality and enabling its abuse.", "def_ko": "AI 시스템에 대한 접근·소유·수익의 격차가 부와 생산 역량, 경제적·정치적 권력을 소수에게 집중시켜 사회적 불평등을 심화시키고 그 오남용을 초래하는 리스크."}, {"id": "G_SYS_CONTEST", "domain": "General AI", "area": "SYS", "title_en": "Non-Contestability", "title_ko": "이의제기 차단", "def_en": "The risk that users are given insufficient means to challenge, review, correct, appeal, or seek alternatives to AI-assisted judgments, recommendations, or decisions, thereby limiting rights protection and outcome validation.", "def_ko": "AI의 판단·추천·결정에 대해 이용자가 이의제기·검토·정정·항변·대안 탐색을 요청할 절차적 수단이 충분히 제공되지 않아 권리 보호와 결과 정당성 검증이 약화되는 리스크."}, {"id": "G_SYS_CONTEXT", "domain": "General AI", "area": "SYS", "title_en": "Context-Awareness Failure", "title_ko": "맥락 인식 실패", "def_en": "The risk that an AI system fails to adequately recognize, retain, or apply the relevant context of an interaction—including prior conversational turns, the user's situation and intent, the task at hand, and applicable jurisdictional, cultural, or institutional norms—producing responses or actions that are incoherent, inappropriate, or misaligned with the actual context.", "def_ko": "AI 시스템이 이전 대화 맥락, 사용자의 상황·의도, 수행 중인 과제, 적용되는 관할·문화·제도 규범 등 상호작용에 필요한 맥락을 충분히 인식·유지·반영하지 못하여, 실제 맥락과 어긋나거나 부적절하거나 일관되지 않은 응답·행동을 산출하는 리스크."}, {"id": "G_SYS_EVAL", "domain": "General AI", "area": "SYS", "title_en": "Evaluation and Assurance Failure", "title_ko": "평가·검증 실패", "def_en": "The risk that an AI system's capabilities, safety, or risks cannot be validly measured, verified, or audited—because evaluations lack construct validity, coverage, or contextual fidelity, produce unreliable or non-reproducible results, or fail to detect actual behavior—leading to false assurance and unsafe deployment or governance decisions.", "def_ko": "평가 지표의 타당성·포괄성·맥락 정합성 부족이나 결과의 비신뢰성·재현 불가, 실제 동작 미탐지 등으로 AI 시스템의 능력·안전·리스크를 타당하게 측정·검증·감사하지 못하여, 잘못된 안전성 확신에 근거해 배포·거버넌스 의사결정이 이루어지는 리스크."}, {"id": "G_SYS_INCONS", "domain": "General AI", "area": "SYS", "title_en": "Inconsistency", "title_ko": "비일관성", "def_en": "The risk that an AI system produces contradictory or substantially different outputs for identical or materially similar inputs, situations, or facts—arising from output variability rather than from missing context—undermining predictability and reliability.", "def_ko": "동일하거나 실질적으로 유사한 입력·상황·사실관계에 대해, 맥락 누락이 아닌 출력 변동성으로 인해 상이하거나 모순된 결과를 생성하여 예측가능성과 신뢰성을 저해하는 리스크."}, {"id": "G_SYS_INPUT", "domain": "General AI", "area": "SYS", "title_en": "Input Interpretation Error", "title_ko": "입력 해석 오류", "def_en": "The risk that an AI system misinterprets the meaning of user input, context, an object, or a scene, producing an inaccurate or harmful output, decision, or action. When the instruction is understood but physical hazards or safety constraints are omitted from task planning, the risk is assigned to P_SYS_TASKPLAN; failures in path or motion planning, control, or actuation for an otherwise valid plan are assigned to P_SYS_CONTROL.", "def_ko": "AI 시스템이 사용자 입력, 맥락, 객체 또는 장면의 의미를 잘못 해석하여 부정확하거나 유해한 출력·판단·행동을 생성하는 리스크. 지시의 의미는 이해했지만 물리적 위험이나 안전 제약을 과업 계획에 반영하지 못한 경우는 P_SYS_TASKPLAN, 타당한 계획의 경로·동작 계획·제어·구동 결함은 P_SYS_CONTROL로 분류한다."}, {"id": "G_SYS_MISINFO", "domain": "General AI", "area": "SYS", "title_en": "Misinformation", "title_ko": "허위정보", "def_en": "The risk that an AI system generates, conveys, or amplifies false, unverified, or fabricated information—including hallucinated content—or presents misleading content as fact in its outputs, thereby distorting decision-making by individuals, organizations, or society.", "def_ko": "AI 시스템이 환각(hallucination)을 포함해 존재하지 않거나 검증되지 않은 허위·조작 정보를 사실처럼 출력으로 생성·전달·증폭하여 개인·조직·사회의 의사결정을 왜곡하는 리스크."}, {"id": "G_SYS_OEXT", "domain": "General AI", "area": "SYS", "title_en": "Over-Extension", "title_ko": "역량 초과 수행", "def_en": "The risk that an AI system performs, or presents itself as able to perform, tasks beyond its validated capabilities, authority, expertise, or scope, inducing misplaced trust or decisions.", "def_ko": "AI 시스템이 검증된 역량·권한·전문성·범위를 넘어선 과제를 수행하거나 수행 가능한 것처럼 제시하여 이용자의 잘못된 신뢰나 의사결정을 유발하는 리스크."}, {"id": "G_SYS_OREF", "domain": "General AI", "area": "SYS", "title_en": "Over-Refusal", "title_ko": "과도한 거절", "def_en": "The risk that an AI system unnecessarily restricts or refuses information, assistance, or options that could be safely provided, thereby impairing users' rights, safety, or legitimate objectives.", "def_ko": "안전하게 제공 가능한 정보·지원·선택지를 불필요하게 제한·거부하여 이용자의 권리·안전·정당한 목적 달성을 저해하는 리스크."}, {"id": "G_SYS_OVERCONF", "domain": "General AI", "area": "SYS", "title_en": "Overconfidence", "title_ko": "과도한 확신", "def_en": "The risk that an AI system presents judgments, predictions, or actions with unwarranted certainty despite uncertainty, limited information, or the possibility of error, or proceeds without verification, halting, or escalation, leading to erroneous outcomes.", "def_ko": "불확실성·정보 부족·오류 가능성에도 불구하고 부당한 확신으로 판단·예측·행동을 제시하거나, 확인·중단·에스컬레이션 없이 진행하여 잘못된 결과를 초래하는 리스크."}, {"id": "G_SYS_PERF", "domain": "General AI", "area": "SYS", "title_en": "Out-of-Domain Performance Degradation", "title_ko": "운영영역 이탈 성능 저하", "def_en": "The risk that an AI system fails to generalize under conditions outside its validated operating domain—such as data distribution shift, low-resource or rare inputs, corner cases, or deployment beyond the system's validated capabilities—resulting in degraded performance and reliability and producing inaccurate or unstable outcomes.", "def_ko": "AI 시스템이 검증된 운영영역(validated operating domain)을 벗어난 조건 — 데이터 분포 이동(drift), 저자원·희소 입력, 코너 케이스, 또는 시스템의 검증된 역량 범위를 넘어선 배치 등 — 에서 일반화에 실패하여 성능과 신뢰성이 저하되고, 부정확하거나 불안정한 결과를 산출하는 리스크."}, {"id": "G_SYS_POLICY", "domain": "General AI", "area": "SYS", "title_en": "Confidential Information Disclosure", "title_ko": "기밀정보 노출", "def_en": "The risk that an AI system discloses, infers, extracts, or shares protected non-public confidential information without authorisation—including system prompts, internal policies, safeguards, model architecture, training or evaluation data, model weights, or business trade secrets—or fails to protect it, thereby compromising confidentiality and legitimate economic interests.", "def_ko": "AI 시스템이 시스템 프롬프트·내부 정책·안전장치·모델 구조·학습/평가 데이터·모델 가중치·기업 영업비밀 등 보호되는 비공개 기밀정보를 권한 없이 노출·추론·추출·공유하거나 이를 충분히 보호하지 못하여, 기밀성과 정당한 경제적 이익을 침해하는 리스크."}, {"id": "G_SYS_SECADV", "domain": "General AI", "area": "SYS", "title_en": "Security and Adversarial Robustness Failure", "title_ko": "보안·적대적 견고성 실패", "def_en": "The risk that an AI system is compromised by adversarial inputs, jailbreaks, prompt injection, data poisoning, backdoors, or cyberattacks on its models, interfaces, or infrastructure, bypassing safeguards or enabling unauthorized access, manipulation, or disruption—including cases where such compromise propagates to agentic or embodied systems and manifests as unsafe actions.", "def_ko": "적대적 입력·탈옥·프롬프트 인젝션·데이터 오염·백도어 또는 모델·인터페이스·인프라에 대한 사이버 공격으로 안전장치가 우회되거나 무단 접근·조작·중단이 발생하는 리스크(이러한 침해가 에이전틱·체화형 시스템으로 전이되어 안전하지 않은 행동으로 발현되는 경우를 포함)."}, {"id": "G_SYS_TRANS", "domain": "General AI", "area": "SYS", "title_en": "Lack of Transparency", "title_ko": "투명성 부족", "def_en": "The risk that a system's decision-making processes, rationale, and capabilities or limitations are insufficiently transparent or explainable, making it difficult for users and society to understand, verify, or trust its outputs, thereby weakening oversight and accountability.", "def_ko": "AI 시스템의 의사결정 과정·근거·능력·한계가 충분히 공개·설명되지 않아 이용자와 사회가 결과를 이해·검증·신뢰하기 어려워지고 감독과 책임 확보가 저해되는 리스크."}, {"id": "A_INT_CASCADE", "domain": "Agentic AI", "area": "INT", "title_en": "Cascading Failure and Instability", "title_ko": "연쇄 실패·불안정", "def_en": "The risk that an error, output, or action from one agent, tool, or workflow propagates across other agents, connected systems, or multi-robot operations, amplifying failure and causing system-level instability or widespread harm.", "def_ko": "한 에이전트, 도구 또는 워크플로의 오류·출력·행동이 다른 에이전트, 연결된 시스템 또는 다중 로봇 운용으로 전파되어 실패가 증폭되고 시스템 수준의 불안정이나 광범위한 피해를 초래하는 리스크."}, {"id": "A_INT_COLLUSION", "domain": "Agentic AI", "area": "INT", "title_en": "Collusion", "title_ko": "담합", "def_en": "The risk that multiple AI agents explicitly agree or implicitly coordinate to manipulate competition, prices, resource allocation, or information flows, harming users, markets, or the public interest.", "def_ko": "여러 AI 에이전트가 명시적 합의나 암묵적 조율을 통해 경쟁·가격·자원 배분·정보 흐름을 부당하게 조정하여 이용자·시장·공공의 이익을 해치는 리스크."}, {"id": "A_INT_CONFLICT", "domain": "Agentic AI", "area": "INT", "title_en": "Competitive Conflict", "title_ko": "경쟁적 갈등", "def_en": "The risk that AI agents compete for resources or pursue conflicting objectives in ways that impair other actors' performance, safety, or rights, or create externalities that weaken safety constraints.", "def_ko": "여러 AI 에이전트가 자원 확보 또는 상충하는 목표 달성을 위해 경쟁하면서 다른 행위자의 성과·안전·권리를 저해하거나 안전 제약을 약화하는 외부효과를 초래하는 리스크."}, {"id": "A_INT_COORD", "domain": "Agentic AI", "area": "INT", "title_en": "Coordination Failure", "title_ko": "협조 실패", "def_en": "The risk that multiple AI agents fail to allocate roles, share state, hand over tasks or control, or resolve deadlock, thereby undermining a common objective or safe operation.", "def_ko": "여러 AI 에이전트가 역할을 적절히 분담하고 상태를 공유하며 과업과 제어권을 인계하지 못하거나 교착 상태를 해소하지 못해 공동 목표 달성이나 안전한 운용에 실패하는 리스크."}, {"id": "A_INT_OVERSIGHT", "domain": "Agentic AI", "area": "INT", "title_en": "Human Oversight and Control-Transfer Failure", "title_ko": "인간 감독·제어권 인계 실패", "def_en": "The risk that human review, approval, intervention, authority revocation, or control transfer required for operating an AI agent is not performed effectively because of insufficient or excessive information, poor timing, unclear state indication, ineffective intervention mechanisms, approval fatigue, or automation bias.", "def_ko": "AI 에이전트 운용에 필요한 사람의 검토·승인·개입·권한 철회·제어권 인계가 정보 부족이나 과잉, 부적절한 시점, 불명확한 상태 표시, 작동하지 않는 개입 수단, 승인 피로 또는 자동화 편향으로 실효성 있게 수행되지 못하는 리스크."}, {"id": "A_SYS_AUTH", "domain": "Agentic AI", "area": "SYS", "title_en": "Excessive Authority and Agency", "title_ko": "과도한 권한·행위주체성", "def_en": "The risk that an AI agent is granted excessive authority or exercises, redelegates, or expands authority beyond its approved delegation scope, producing consequential external effects. Automated execution that remains within approved policy and authorization is not itself a failure.", "def_ko": "AI 에이전트에 과도한 권한이 부여되거나 에이전트가 승인된 위임 범위를 벗어나 권한을 행사·재위임·확대하여 중대한 외부 영향을 초래하는 리스크. 정책과 승인 절차에 따라 허용된 자동 실행 자체는 실패로 보지 않는다."}, {"id": "A_SYS_DECEPT", "domain": "Agentic AI", "area": "SYS", "title_en": "Deception and Concealment", "title_ko": "기만·은폐", "def_en": "The risk for which observable evidence shows that an AI agent misrepresents, omits, or conceals relevant information, actions, states, or outcomes to evade oversight or correction. Resistance to termination or modification without concealment is assigned to A_SYS_GOAL when supported by goal-pursuit evidence; ineffective intervention mechanisms are assigned to A_INT_OVERSIGHT; and failure to respect execution limits is assigned to A_SYS_RESOURCE.", "def_ko": "AI 에이전트가 감독이나 교정을 회피하기 위해 관련 정보, 행동, 상태 또는 결과를 의도적으로 오표현·누락·은폐했다는 관찰 가능한 증거가 있는 리스크. 은폐 없는 종료 거부나 수정 저항은 목표 추구의 증거가 있으면 A_SYS_GOAL, 개입 수단의 미작동은 A_INT_OVERSIGHT, 실행 한도 미준수는 A_SYS_RESOURCE로 분류한다."}, {"id": "A_SYS_EXEC", "domain": "Agentic AI", "area": "SYS", "title_en": "Task Execution and Tool-Use Failure", "title_ko": "과업 수행·도구 실행 실패", "def_en": "The risk that an AI agent, within an approved objective and authority scope, incorrectly selects task decomposition or order, a tool, target, argument, execution precondition, or completion condition, changing external state contrary to the intended outcome. Errors in operating physical devices through APIs or IoT are included when physical perception, control, or actuation is not the dominant mechanism.", "def_ko": "AI 에이전트가 승인된 목표와 권한 범위 안에서 과업 분해·순서, 도구, 대상, 인자, 실행 전제 또는 완료 조건을 잘못 선택하여 외부 상태를 의도와 다르게 변경하는 리스크. API나 IoT를 통한 물리 기기 조작 오류도 물리적 지각·제어·구동이 지배적 기제가 아니면 이 범주에 포함한다."}, {"id": "A_SYS_GOAL", "domain": "Agentic AI", "area": "SYS", "title_en": "Goal Misalignment", "title_ko": "목표 불일치", "def_en": "The risk that an AI agent forms or pursues goals or instrumental subgoals that conflict with approved objectives, constraints, or priorities, causing unintended outcomes. Observable self-preservation, resource acquisition, or resistance to termination is included when it departs from those approved objectives, even without concealment.", "def_ko": "AI 에이전트가 승인된 목표·제약·우선순위와 불일치하는 목표 또는 수단적 하위 목표를 형성·추구하여 의도하지 않은 결과를 초래하는 리스크. 은폐 없이 나타나는 자기 보존, 자원 획득 또는 종료 저항도 승인된 목표와의 불일치가 관찰되면 포함한다."}, {"id": "A_SYS_MEMSTATE", "domain": "Agentic AI", "area": "SYS", "title_en": "Persistent Memory and Task-State Integrity Failure", "title_ko": "지속 메모리·과업 상태 무결성 실패", "def_en": "The risk that an AI agent fails to verify the provenance of persistent memory or task state, maintain its currency and consistency, or preserve boundaries across users and tasks, causing action based on stale, incorrect, or commingled state.", "def_ko": "AI 에이전트가 지속 메모리나 과업 상태의 출처 검증, 최신성·일관성 유지, 사용자·과업 간 경계 관리에 실패하여 오래되거나 잘못되거나 서로 섞인 상태에 근거해 행동하는 리스크."}, {"id": "A_SYS_RESOURCE", "domain": "Agentic AI", "area": "SYS", "title_en": "Resource Budget and Execution Termination Failure", "title_ko": "자원 예산·실행 종료 실패", "def_en": "The risk that an AI agent fails to respect execution limits or termination conditions for cost, time, tool calls, retries, or delegation depth, causing unnecessary continuation, persistent subagents, or resource exhaustion.", "def_ko": "AI 에이전트가 비용·시간·도구 호출·재시도·위임 깊이 등의 실행 한도나 종료 조건을 지키지 못해 불필요한 작업 지속, 하위 에이전트의 잔존 또는 자원 고갈을 초래하는 리스크."}, {"id": "A_SYS_SELFCOR", "domain": "Agentic AI", "area": "SYS", "title_en": "Self-Correction Failure", "title_ko": "자기 교정 실패", "def_en": "The risk that an AI agent, after detecting an error or risk signal, fails to respect retry limits, choose an appropriate stop or recovery action, or verify the result of correction, thereby repeating or amplifying the error. General continuation without verification due to overconfidence is assigned to G_SYS_OVERCONF.", "def_ko": "AI 에이전트가 오류나 위험 신호를 감지한 뒤 재시도 한도를 지키고 중단·복구 방식을 선택하거나 교정 결과를 확인하지 못해 오류를 반복·확대하는 리스크. 확인 없이 계속 진행하는 일반적 과신은 G_SYS_OVERCONF로 분류한다."}, {"id": "A_SYS_TRACE", "domain": "Agentic AI", "area": "SYS", "title_en": "Accountability and Traceability Gap", "title_ko": "책임성·추적성 공백", "def_en": "The risk that an AI agent's tool calls, delegations and approvals, state changes, and external outcomes are not recorded in a linked form, preventing reliable reconstruction or verification of the causes, sequence, and accountability of its actions.", "def_ko": "AI 에이전트의 도구 호출, 위임과 승인, 상태 변경, 외부 결과가 서로 연결된 기록으로 남지 않아 행동의 원인·경로·책임 관계를 재구성하거나 검증하기 어려운 리스크."}, {"id": "P_INT_OBSTRUCT", "domain": "Physical AI", "area": "INT", "title_en": "Shared-Space Obstruction", "title_ko": "공유 공간 점유·이동 방해", "def_en": "The risk that a robot operating or waiting in a shared space blocks or encroaches on pedestrian routes, ramps, entrances, or emergency passages, impairing safe movement and access for mobility-impaired and other users even without physical contact.", "def_ko": "공유 공간에서 운행하거나 대기하는 로봇이 보행 동선·경사로·출입구·비상 통로를 막거나 침범하여 접촉 없이도 보행 약자와 다른 이용자의 안전한 이동과 접근을 저해하는 리스크."}, {"id": "P_INT_SAFETY", "domain": "Physical AI", "area": "INT", "title_en": "Human-Robot Physical Safety Failure", "title_ko": "인간-로봇 물리 안전 실패", "def_en": "The risk that an embodied system, after correctly recognizing a person, fails to perform protective behavior required for separation distance, speed monitoring, contact-force limitation, object handover in collaboration, or intended contact such as care, causing harm to the person. Stopping or slowing in response to human proximity belongs here; failure to transition to a safe state after a fault or collision is assigned to P_SYS_SAFESTATE.", "def_ko": "체화형 시스템이 사람을 올바르게 인식한 뒤에도 이격 거리, 속도 감시, 접촉력 제한, 협업 중 물체 인계, 돌봄 등 의도된 접촉에 필요한 보호 행동을 수행하지 못해 사람에게 위해를 초래하는 리스크. 사람 접근에 따른 정지·감속은 이 범주에 포함하고, 고장이나 충돌 뒤 안전상태 전환 실패는 P_SYS_SAFESTATE로 분류한다."}, {"id": "P_INT_TAMPER", "domain": "Physical AI", "area": "INT", "title_en": "Physical Tampering and Sabotage", "title_ko": "물리적 변조·방해", "def_en": "The risk that a person or other actor physically contacts, blocks, attaches to, replaces, damages, or manipulates an embodied system's sensors, actuators, mechanical components, or safety devices, disrupting perception, action, or safety functions. Non-contact signal injection such as LiDAR spoofing is assigned to G_SYS_SECADV.", "def_ko": "사람이나 다른 행위자가 체화형 시스템의 센서·구동기·기계 부품·안전 장치에 물리적으로 접촉하거나 이를 가림·부착·교체·손상·조작하여 인식·행동·안전 기능을 방해하는 리스크. LiDAR 스푸핑 등 비접촉 신호 주입은 G_SYS_SECADV로 분류한다."}, {"id": "P_SYS_CONTROL", "domain": "Physical AI", "area": "SYS", "title_en": "Unsafe Physical Control and Actuation", "title_ko": "불안전한 물리 제어·구동", "def_en": "The risk that an embodied system, while translating or executing an otherwise valid task plan through path or motion planning, control, or actuation, violates position, speed, force, or stability limits and causes unsafe physical behavior, including excessive speed or force, unstable trajectories, or humanoid falls. Hazardous task-level action selection is assigned to P_SYS_TASKPLAN, and failure to transition to a safe state after an abnormal event is assigned to P_SYS_SAFESTATE.", "def_ko": "체화형 시스템이 타당한 과업 계획을 경로·동작 계획, 제어 또는 구동으로 변환·실행하는 과정에서 위치·속도·힘·안정성 한계를 위반하여 과도한 속도·힘, 불안정한 궤적, 휴머노이드 전도 등 안전하지 않은 물리 행동을 초래하는 리스크. 과업 수준의 위험한 행동 선택은 P_SYS_TASKPLAN, 이상 발생 뒤 안전상태 전환 실패는 P_SYS_SAFESTATE로 분류한다."}, {"id": "P_SYS_HARDWARE", "domain": "Physical AI", "area": "SYS", "title_en": "Hardware and Mechanical Integrity Failure", "title_ko": "하드웨어·기계적 무결성 실패", "def_en": "The risk that failure, degradation, or insufficient structural integrity in an embodied system's power supply, battery, sensors, actuators, connections, or structural components impairs AI perception, action, or safety functions and causes an unsafe physical state or action.", "def_ko": "체화형 시스템의 전원·배터리·센서·구동기·연결부·구조체 등의 고장, 열화 또는 구조 강도 부족이 AI의 지각·행동·안전 기능에 영향을 주어 안전하지 않은 물리 상태나 행동을 초래하는 리스크."}, {"id": "P_SYS_SAFESTATE", "domain": "Physical AI", "area": "SYS", "title_en": "Safety Supervision and Safe-State Transition Failure", "title_ko": "안전 감시·안전상태 전환 실패", "def_en": "The risk that safety supervision or protective functions fail to detect a fault, operating-limit exceedance, collision, or other abnormal condition, or fail to transition in time to an appropriate safe state such as stopping, slowing, maintaining posture, or moving to a safe location, fail to maintain that state, or create a secondary hazard by stopping at an inappropriate time or place.", "def_ko": "고장·운영 한계 이탈·충돌 등 이상 상황을 감지하는 안전 감시 또는 보호 기능이 작동하지 않거나, 정지·감속·자세 유지·안전 위치 이동 등 적절한 안전상태로 제때 전환하거나 그 상태를 유지하지 못하고, 부적절한 시점이나 위치의 정지로 2차 위험을 만드는 리스크."}, {"id": "P_SYS_STATE", "domain": "Physical AI", "area": "SYS", "title_en": "Physical State Estimation and Sensor-Fusion Failure", "title_ko": "물리 상태 추정·센서 융합 실패", "def_en": "The risk that an embodied system fails to estimate the location, pose, motion, contact, force, or spatial map of itself, people, or obstacles, or fails to fuse heterogeneous physical sensor streams such as vision, LiDAR, inertial, tactile, and proprioceptive signals, causing unsafe physical action. Semantic misidentification of whether an object is a person is assigned to G_SYS_INPUT; adversarial signal injection is assigned to G_SYS_SECADV; non-adversarial sensor noise and physical-state estimation errors remain in this category.", "def_ko": "체화형 시스템이 자신, 사람 또는 장애물의 위치·자세·움직임·접촉·힘·공간 지도를 올바르게 추정하지 못하거나 비전·LiDAR·관성·촉각·고유수용성 등 이질적인 물리 센서 스트림을 신뢰성 있게 융합하지 못해 안전하지 않은 물리 행동을 초래하는 리스크. 대상이 사람인지의 의미적 오인식은 G_SYS_INPUT, 공격에 의한 신호 주입은 G_SYS_SECADV로 분류하며, 비적대적 센서 잡음과 물리 상태 추정 오류는 이 범주에 포함한다."}, {"id": "P_SYS_TASKPLAN", "domain": "Physical AI", "area": "SYS", "title_en": "Physical Hazard-Aware Task Planning Failure", "title_ko": "물리 위험 인식·과업 계획 실패", "def_en": "The risk that an embodied AI system, while interpreting and decomposing a task and selecting actions, objects, sequences, and conditions, fails to account for physical hazards and safety constraints such as collision, falling, entrapment, thermal, electrical, or chemical energy, or hazardous substances, so that the planned action itself increases the possibility of harm even when perception and control function normally.", "def_ko": "체화형 AI 시스템이 과업을 해석·분해하고 행동·대상·순서·조건을 정하는 과정에서 충돌·낙하·끼임·열·전기·화학 에너지·위험물질 등 물리적 위험과 안전 제약을 반영하지 못해, 인식과 제어가 정상이어도 계획한 행동 자체가 위해 가능성을 높이는 리스크."}, {"id": "P_SYS_TIMESYNC", "domain": "Physical AI", "area": "SYS", "title_en": "Timing and Communication Synchronization Failure", "title_ko": "실시간 지연·통신 동기화 실패", "def_en": "The risk that information required for an embodied system's sensing, inference, communication, control, or remote intervention loses validity because of latency, loss, reordering, or synchronization failure, and the system nevertheless uses it or fails to respond appropriately, causing unsafe physical behavior.", "def_ko": "체화형 시스템의 관측·추론·통신·제어·원격 개입에 필요한 정보가 지연·손실·순서 역전·동기화 실패로 유효성을 잃었는데도 시스템이 이를 사용하거나 적절히 대응하지 못해 안전하지 않은 물리 행동을 초래하는 리스크."}];
